INSERT INTO `inspirations` (`id`, `user_id`, `raw_text`, `source_note`, `created_at`) VALUES (1, 1, '【标题】上海安福路这家brunch，排队2小时也值得！\n\n【开头钩子】\n周末和闺蜜去安福路，被一家藏在弄堂里的brunch店惊艳到了。\n门口排了长长的队，本来想走，结果旁边小姐姐说\"排了2小时，\n真的好吃\"，果断加入队伍。\n\n【核心内容】\n1. 环境：法式复古装修，暖黄色灯光，窗边位置拍照绝了，随手\n   一拍就是ins风。店里放着爵士乐，氛围很慵懒。\n2. 必点菜品：\n   - 班尼迪克蛋：流心蛋黄+荷兰酱，一口下去超满足，面包底烤\n     得酥脆，吸满酱汁也不会软塌。\n   - 松露蘑菇意面：松露味很浓，蘑菇新鲜，奶油酱汁浓郁但不腻，\n     分量刚好。\n   - 草莓气泡水：颜值超高，草莓果肉+薄荷叶，解腻神器。\n3. 价格：人均120左右，在安福路这个地段算性价比很高了。\n4. 排队攻略：建议周末10点前到，或者工作日下午2点后人少。\n   可以先取号去旁边逛买手店，到号了会微信提醒。\n\n【结尾互动】\n你们还知道安福路哪些宝藏小店？评论区告诉我，下期去探！\n收藏这篇，周末直接冲！\n\n【数据表现】\n点赞2.3w，收藏1.8w，评论800+，评论区高频词：\"地址在哪\"\n\"看起来好好吃\"\"周末就去\"\n', '红书收藏的爆款探店笔记·上海安福路brunch ', '2026-08-24 05:41:55');
