INSERT INTO `inspirations` (`id`, `user_id`, `raw_text`, `source_note`, `created_at`) VALUES (4, 1, '《【品城记】网上无任何资料全靠熟人带！必点蟛蜞汤真的鲜到阿妈都唔认得！_哔哩哔哩_bilibili》（来源：哔哩哔哩）\n首页\n番剧\n直播\n游戏中心\n会员购\n漫画\n赛事\n投稿\n【品城记】网上无任何资料全靠熟人带！必点蟛蜞汤真的鲜到阿妈都唔认得！\n4.2万\n158\n2026-08-22 20:30:00\n个人观点，仅供参考\n1471\n163\n390\n169\n课程总结\n收起全部章节\n关闭课程总结\n暂无课程总结\n说出来你可能不信，我们挖掘到的很多宝藏餐厅，一部分来自于粉丝报料，还有一部分，其实是来自于去过的餐厅老板们的推荐！今天这期节目就是如此！要去的餐厅位于中山，在网上，无论是某点评还是某音，都完全找不到任何资料，但当我们去到现场，却发现里面早已经是高朋满座，原来人家根本不需要宣传，完全就不缺客源！因为就开在河畔，所以这里以吃河鲜为主，尤其值得一提的是这里的蟛蜞汤，当真是鲜到阿妈都唔认得！\n发现《The Dollhouse Dance》\n记录我的美食日常\n河鲜\n探店\n中山美食\n品城记Video\n发消息\n吃吃喝喝，走走逛逛\n关注 59.8万\n中山探店合集\n（2/2）\n自动连播\n11.7万播放\n简介\n订阅合集\n【品城记】探食中山沙溪30年老字号餐厅！紫苏浸牛肉和沙溪扣肉好吃到颠！\n05:44\n【品城记】网上无任何资料全靠熟人带！必点蟛蜞汤真的鲜到阿妈都唔认得！\n06:26\n【品城记】赌你没见过这么多、这么平价的新鲜虾蝲！六种不同做法，几乎每一种都好吃得不得了！安利哥：就算痛风都要吃它！\n品城记本地版\n35.1万\n1760\n【品城记】广州的烟火气回来了！这里都是老广偏爱的味道！再过几年还能吃到吗？\n品城记本地版\n89.6万\n5130\n【品城记】干鲍鱼翅汤28一盅，牛鞭汤10块钱一盅，这价格真的就是益街坊了！\n品城记Video\n1.6万\n53\n【品城记】安利哥醒你猪杂粥好食秘诀！新鲜到变尿酸教父都抵！\n品城记本地版\n47.9万\n3559\n【姚大秋食游记】当你被业绩、KPI、最后期限压到喘不过气的时候，太适合来这里放空几天了！\nLoyieeeee\n14.0万\n1458\n【品城记】四姐弟撑起一家老字号，出品甩很多大酒楼一条街！\n品城记Video\n7.7万\n242\n【品城记】一家开在村口的家常菜小店，竟然能让安利哥“好吃”叫个不停！还一连干下几碗米饭！有冇咁好食啊？\n品城记本地版\n41.0万\n1449\n【品城记】中山厨师村食游记！村里面六个人就有一个是厨师！\n品城记Video\n18.1万\n525\n【品城记】来崖口，闭眼吃就完了！从云吞到煲仔饭到海鲜到烧猪，总有一款合你口味！\n品城记Video\n21.3万\n633\n【品城记】八个菜埋单200块都不到！四个大男人吃到扶墙而出！\n品城记Video\n5.1万\n173\n【品城记】每天捞到什么就卖什么，极致新鲜，堪称吃鱼人的天堂！\n品城记Video\n5.4万\n52\n【品城记】88一只鸡！38一斤虾！虽然吃到一半停电，但这顿饭真的顶瘾！\n品城记Video\n7.1万\n108\n【品城记】昆明│昆明不应该只是一个旅游中转站，这儿好吃好玩的实在太多了！\n品城记Video\n37.2万\n5294\n【品城记】人手不足惟有「自助服务」，但丝毫不影响这里生意火爆！\n品城记Video\n3.3万\n51\n【品城记】10盘菜埋单300都不到！这家宵夜大排档真是好味又抵食！\n品城记Video\n6.4万\n112\n全中国最毒的食材，云南人却抢着吃？\n盗月社食遇记\n40.7万\n920\n【品城记】安利哥河鲜档排雷指南！老板：来多几个这样的人，生意都唔洗做！\n品城记本地版\n44.0万\n2291\n【品城记】打卡芳村“小众”台山菜馆！招牌黄鳝饭、五味鹅绝对值得二刷！\n品城记Video\n7.1万\n113\n【品城记】炉底糍、蛤篓饭……这些好吃的东西，怕是只有台山本地才能吃到吧？！\n品城记Video\n5.3万\n207\n【品城记搬运】好吃到安利哥连爆粗口！顺德人怎么就能把简单的食材做到如此美味呢？\n天基星星\n4.7万\n95\n展开\n参赛赢丰厚奖金！>>\n小窗\n客服\n顶部\n赛事库\n课堂\n2021拜年纪', '链接抓取：https://www.bilibili.com/video/BV1Ly8F6MEFe/?spm