INSERT INTO `topics` (`id`, `user_id`, `inspiration_id`, `title`, `highlights`, `feasibility`, `cost_note`, `why`, `source`, `status`, `created_at`, `priority`, `tags`) VALUES (2, 1, 1, '安福路brunch排队2小时实测：值不值？附避坑点单攻略', '[\"真实排队2小时后的第一视角体验，打消观众“值不值”的疑虑\", \"班尼迪克蛋流心+酥脆面包底，口感细节逐帧描述，馋人\", \"松露蘑菇意面、草莓气泡水的优缺点实评，不吹不黑\", \"人均120在安福路算什么水平，帮观众算性价比\", \"给出错峰时间+微信取号逛店技巧，让攻略可抄\", \"结尾抛“安福路还有哪些宝藏店”征集，引评论互动\"]', 'quick', '周末高峰期需排队约2小时，人均约120元，往返安福路交通成本约20元；拍摄设备自带，无需额外预算。若UP主能工作日或早10点前到场，可减少排队时间。', '原爆款笔记数据亮眼（点赞2.3w、收藏1.8w），证明年轻人对安福路brunch话题有强兴趣。UP主定位线下体验/探店，日更需要稳定产出，此选题短平快、容易复刻，且自带打卡属性，适合立刻做。', 'extract', 'inbox', '2026-08-24 05:41:55', 'mid', '');
INSERT INTO `topics` (`id`, `user_id`, `inspiration_id`, `title`, `highlights`, `feasibility`, `cost_note`, `why`, `source`, `status`, `created_at`, `priority`, `tags`) VALUES (3, 5, 2, '我带着外国室友去看了全网骂的《牛来》，他居然被感动哭了？', '[\"国内骂声一片，外网却吹上天，这反差我先冲了\", \"买票时遇到隔壁老外也在买，当场唠了起来\", \"放映厅真实反应：前半场爆笑，后半场沉默\", \"散场后随机问路人：你觉得是烂片还是神片？\", \"回家后偷偷循环片尾曲，真香了\", \"弹幕提问：你们还想看我去看哪部“神作”？\"]', 'quick', '成本极低：一张电影票+半天拍摄时间。需提前确认本地影院是否还有排片，手机拍摄即可，无需额外设备。', '《牛来》正在话题风口，中外口碑两极反差天然适合生活区做体验型vlog。不需要专业影评，只需要真实反应和情绪输出，完美贴合日常切片+情绪共鸣的人设，热点时效性强，越早发越有流量。', 'extract', 'inbox', '2026-08-24 08:05:33', 'mid', '[]');
INSERT INTO `topics` (`id`, `user_id`, `inspiration_id`, `title`, `highlights`, `feasibility`, `cost_note`, `why`, `source`, `status`, `created_at`, `priority`, `tags`) VALUES (4, 5, 3, '本来只想逛逛快闪店，结果排了3小时货架空空的', '[\"排队3小时自己从期待到麻木的真实心理变化\", \"进店后货架空、服务差、灯光全靠手机补光的落差瞬间\", \"评论区一边骂一边求“到底值不值得”的矛盾情绪\", \"最后给一个“值不值得”的个人判断，不劝退也不硬夸\"]', 'quick', '低预算，周末半天时间+往返交通即可，手机拍摄就能完成，无需额外设备。', '快闪店话题自带争议热度，评论区两级分化容易引发弹幕讨论；排队到落差的叙事结构天然符合‘小事+转折’的频道定位，且生活感强、好拍，适合立刻做。', 'extract', 'inbox', '2026-08-24 08:45:59', 'mid', '[]');
INSERT INTO `topics` (`id`, `user_id`, `inspiration_id`, `title`, `highlights`, `feasibility`, `cost_note`, `why`, `source`, `status`, `created_at`, `priority`, `tags`) VALUES (5, 1, 4, '全网搜不到却满座的河畔河鲜店｜蟛蜞汤实测：鲜到阿妈都唔认得？', '[\"网上零资料，某点评某音全搜不到，只靠熟人带路\", \"开在河畔，以河鲜为主，招牌蟛蜞汤是必点\", \"现场高朋满座，老板不做宣传也不缺客源\", \"\'鲜到阿妈都唔认得\'的夸张说法，实测验证真假\", \"对比普通河鲜汤，给出值不值得专门跑一趟的结论\"]', 'deferred', '需先通过粉丝或同行获取具体位置，往返中山交通和时间成本较高；单店单品测试未必覆盖往返成本，建议并入中山扫街或高成本周期选题', '原爆款靠神秘感、地域特色和夸张口感引发好奇，契合体验派\'先替你踩雷\'的定位；但店铺无公开资料，寻店门槛高且异地成本大，属于高成本选题，暂缓启动更合理', 'extract', 'inbox', '2026-08-24 08:49:26', 'mid', '[]');
