INSERT INTO `topics` (`id`, `user_id`, `inspiration_id`, `title`, `highlights`, `feasibility`, `cost_note`, `why`, `source`, `status`, `created_at`, `priority`, `tags`) VALUES (17, 12, 16, '记录外卖路上的城市温暖瞬间', '[\"外卖碎片记录城市生活\", \"路上遇到的有趣人事物\", \"治愈系正能量传递\", \"大学生视角真实记录\", \"用瓶子传递温暖互动\"]', 'deferred', '选题属生活记录类，非旅游/展会，需换账号或转型后执行', '原文为外卖生活正能量记录，与城市漫游及展会探访定位不符，强行拍摄会偏离人设，故暂不立项', 'extract', 'inbox', '2026-08-24 14:36:43', 'mid', '[]');
INSERT INTO `topics` (`id`, `user_id`, `inspiration_id`, `title`, `highlights`, `feasibility`, `cost_note`, `why`, `source`, `status`, `created_at`, `priority`, `tags`) VALUES (18, 14, 17, '实测上海快闪店排队3小时值不值', '[\"真实排队3小时记录全程\", \"门口打卡机位密集，悬念拉满\", \"进店货架空，服务差强人意\", \"灯光暗到必须手机补光\", \"评论区骂完还是求值不值\"]', 'quick', '仅需周末时间与交通成本，无额外道具门槛', '贴合真实小事+消费决策定位，排队落差自带转折，预算低可快速执行', 'extract', 'inbox', '2026-08-25 06:17:13', 'mid', '[]');
INSERT INTO `topics` (`id`, `user_id`, `inspiration_id`, `title`, `highlights`, `feasibility`, `cost_note`, `why`, `source`, `status`, `created_at`, `priority`, `tags`) VALUES (19, 5, 18, '推荐4个私藏极品网站', '[\"4个私藏网站一次性公开\", \"阿里千问最强最新版体验\", \"科技猎手黑科技经验分享\", \"老湿1分钟快速推荐\"]', 'deferred', '拍摄成本低，但需另开科技账号', '内容属科技区资源推荐，与宠物日常救助科普定位冲突，且可能涉及灰色资源，暂不立项', 'extract', 'inbox', '2026-08-25 08:52:27', 'mid', '[]');
INSERT INTO `topics` (`id`, `user_id`, `inspiration_id`, `title`, `highlights`, `feasibility`, `cost_note`, `why`, `source`, `status`, `created_at`, `priority`, `tags`) VALUES (20, 5, 19, '对比中外超市物价，宠物UP主能拍吗', '[\"中美超市100元购物对比反差大\", \"山姆红黑榜测评引578万播放\", \"日本超市百元挑战播放破千万\", \"超市测评属于美食区爆款赛道\"]', 'deferred', '需跨国或异地采购，成本高；且与宠物频道人设严重不符。', '原文为美食测评内容，与宠物日常/救助定位冲突，观众预期不符，不建议跟拍。', 'extract', 'inbox', '2026-08-25 08:53:14', 'mid', '[]');
INSERT INTO `topics` (`id`, `user_id`, `inspiration_id`, `title`, `highlights`, `feasibility`, `cost_note`, `why`, `source`, `status`, `created_at`, `priority`, `tags`) VALUES (21, 5, 20, '对比中美超市100元购买力', '[\"中国vs美国超市价格直接对比\", \"100元购买力差异冲击性强\", \"原视频113.8万播放热度高\"]', 'deferred', '拍摄成本可控，但内容与宠物频道定位不符', '美食测评与动物圈人设冲突，无法融入治愈/救助/科普，暂不执行', 'extract', 'inbox', '2026-08-25 08:54:05', 'mid', '[]');
INSERT INTO `topics` (`id`, `user_id`, `inspiration_id`, `title`, `highlights`, `feasibility`, `cost_note`, `why`, `source`, `status`, `created_at`, `priority`, `tags`) VALUES (22, 15, 21, '测评不刷碗免煮速食一桶两吃', '[\"“网红不刷碗”免煮速食测评\", \"主打一桶两吃\", \"播放627.6万、点赞7万、投币4945\", \"测评榜分封神/名士/凡人/妖魔四级\", \"“口味千人千味\", \"仅代表我个人”\", \"标题反问“你真豪到我了！”\"]', 'quick', '需采购免煮速食产品，并跨时尚区做美食测评，定位冲突', '原文为美食测评，与罗墩墩时尚区穿搭美妆定位不符，观众预期不一致，不建议直接跟进。', 'extract', 'inbox', '2026-08-26 13:34:04', 'mid', '[]');
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (1, 1, 1, 'test', '[{\"title\": \"同一道招牌菜，我连吃8家，谁才是真·第一？\", \"angle\": \"横向盲测：选一道常见菜，在同一时段、同类店面里按固定维度打分，用表格和实录呈现差异，不靠嘴吹。\", \"audience\": \"有选择困难症、点菜前爱看真实对比的理性年轻人\", \"cost\": \"低：市区内8家小店餐费+交通，约300元，无额外设备\", \"hook\": \"同一道菜，8家店，我吃完直接给你排出名次，附打分表。\", \"why_different\": \"多数探店是单店安利，我用控制变量的横向测评，把主观口味拆成可比较的数据，评论区可以直接按维度追问，符合理性答疑人设。\"}, {\"title\": \"专挑全城评分最低的店吃，是真难吃还是被冤枉？\", \"angle\": \"反向探店：从差评榜/低分店入手，逐条核验差评是否属实，用镜头记录真实的就餐流程和菜品状态。\", \"audience\": \"爱看避雷、猎奇反转、对网红店审美疲劳的年轻人\", \"cost\": \"低到中：3-4家低分店餐费+往返交通，约400元，无需特殊设备\", \"hook\": \"评分2.8的店，我偏要去吃，看它到底是垃圾还是宝藏。\", \"why_different\": \"主流探店只讲好店，我用低分店做对冲，天然有悬念和冲突感，同时坚持实拍实吃，不预设立场，最后给“可吃/不可吃”的结论。\"}, {\"title\": \"花2000块带仪器探店：爆火炸鸡的油，到底换没换？\", \"angle\": \"科学检测体验：携带便携油质检测仪、试纸等工具，在店内公开测油、测温度、测卫生指标，用数据还原后厨真相。\", \"audience\": \"关注食品安全、爱看硬核知识科普、愿意为健康避雷的年轻人\", \"cost\": \"中高：便携检测仪约1500元，试纸耗材+餐费约500元\", \"hook\": \"这家的炸鸡天天排队，我把检测仪带进店，测完你可能不敢再吃。\", \"why_different\": \"跳出“好不好吃”的感官评价，用可量化的卫生数据做内容壁垒，别人没法轻易复制，也强化体验派“重证据、少情绪”的标签。\"}]', NULL, '2026-08-24 05:35:13', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (2, 1, 1, 'test', '[{\"title\": \"同一道菜，10家店盲测排雷：最贵的不一定最好吃\", \"angle\": \"横向盲测+标准化评分：选同一道菜，在10家店分别购买，用牛皮纸袋遮住店名，按口味、分量、性价比打分，最后揭晓排名并复盘评分依据。\", \"audience\": \"有选择困难、常为去哪家店纠结的年轻消费者。\", \"cost\": \"中：10家店菜品购买费用、市内交通费，拍摄约2天，后期评分图表制作。\", \"hook\": \"这道菜最贵一份98，最便宜一份22。我全部买回来盲测，猜猜第一名是谁？\", \"why_different\": \"不是单店探店，而是以同一菜品为样本做横向对比，结论基于统一标准而非个人偏好，符合理性测评调性。\"}, {\"title\": \"100元城中村挑战：连吃5顿，测饱腹感和营养性价比\", \"angle\": \"极限预算+营养数据实测：用100元在城中村解决一天5顿，记录每顿价格、热量、蛋白质，并对比同等花费下的快餐店数据。\", \"audience\": \"学生党、月光族、想省钱又想吃得实在的年轻人。\", \"cost\": \"低：100元餐费+一天拍摄，无其他场景费用。\", \"hook\": \"100块钱能在城中村吃几顿？我吃了5顿，还算了每克蛋白质要花多少钱。\", \"why_different\": \"把探店变成消费实验，用计算和数据说话，而不是展示食欲，成本低且容易复制成系列。\"}, {\"title\": \"被200条差评包围的店，我带着秤去现场复核\", \"angle\": \"差评调查式探店：从外卖平台筛选差评集中、争议大的店铺，打印差评截图，到店点同款，现场称重、测温度、核对份量，验证差评是否属实。\", \"audience\": \"常点外卖、担心商家图文不符、看重食品安全和份量的用户。\", \"cost\": \"高：需跨区/跨城探店、多次购买菜品、定制称重工具和差评证据字幕，后期核查成本高。\", \"hook\": \"这家店被200条差评说又贵又少，我带着电子秤直接到店，结果和差评完全相反。\", \"why_different\": \"从差评切入做调查式内容，用证据回应争议，比普通探店更有信息量和传播潜力，同时强化理性答疑的人设。\"}]', NULL, '2026-08-24 05:35:31', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (3, 1, 1, 'test', '[{\"title\": \"网红店宣传的“天花板”，我用秤和温度计拆穿了\", \"angle\": \"以实测数据验证网红店宣传点：分量、温度、出餐时间、宣称的食材产地。不靠主观口味，用可量化证据下结论，每期给出“可冲/可尝/可避雷”的理性结论。\", \"audience\": \"对营销免疫、喜欢逻辑拆解的理性吃货，以及数码/测评类内容爱好者。\", \"cost\": \"中成本：约200-400元/期，需便携电子秤、红外温度计、计时器，外加购买多份餐品。\", \"hook\": \"别急着冲，这条视频先让老板的广告语过一下秤。\", \"why_different\": \"大多数探店只讲口味和环境，本系列用实验方法把店家的“极致”承诺变成可验证的指标，评论区可直接点名下一家被测品牌，适合理性答疑互动。\"}, {\"title\": \"50元在上海吃一天，我选了这三家店\", \"angle\": \"极限预算挑战：用50元吃遍城市某区域，对比不同店单品性价比，结合饱腹感和步行路线计算“满足/元”，最后给出可抄作业的路线排名。\", \"audience\": \"学生党、预算敏感的打工人、喜欢城市探索和穷游攻略的年轻人。\", \"cost\": \"低成本：每期餐费50-100元，只靠手机拍摄和公共交通，无额外设备支出。\", \"hook\": \"今天不是探店，是生存测试。50块，我能不能在这个区吃饱吃好？\", \"why_different\": \"不对单店做孤立评价，而是以“路线攻略+性价比排名”的方式呈现，观众可直接抄作业，评论区可晒出自己城市的50元吃法，互动门槛低。\"}, {\"title\": \"一个人吃火锅，店员全程把我当空气？独食服务观察实录\", \"angle\": \"从独食者视角测评餐厅对一个人的服务态度、座位设计、分量友好度和社恐压力指数，不做口味排名，而是记录“敢不敢一个人走进这家店”的真实体验。\", \"audience\": \"独自生活的年轻人、社恐人群、经常一个人吃饭但不好意思进店的观众。\", \"cost\": \"中高成本：一期至少测5家店，餐费约400-600元，需要手机稳定器/三脚架自拍，剪辑工作量较大。\", \"hook\": \"你试过一个人吃火锅吗？不是没人陪，是我想知道——这家店到底欢迎不欢迎我。\", \"why_different\": \"聚焦“独食体验”这一细分场景，避开传统口味测评，关注服务细节和心理感受，给同样一个人吃饭的观众一份“敢进店”清单，评论区征集“最敢接待一个人的店”。\"}]', 0, '2026-08-24 05:36:02', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (4, 5, 3, '我带着外国室友去看了全网骂的《牛来》，他居然被感动哭了？', '[{\"title\": \"我带外国室友看《牛来》全网骂，他哭到隐形眼镜移位？\", \"angle\": \"不做吐槽，也不做辩护，把镜头对准“一个不了解中国网络语境的外国人”的观看体验，从文化差异切入谈中国式亲情和牺牲叙事，用他的眼泪反衬网络骂声背后的集体情绪。\", \"audience\": \"喜欢跨文化话题、对深度情绪共鸣敏感的生活区观众，以及本身对《牛来》争议好奇但不想看纯骂战的人群。\", \"cost\": \"低：一台手机或相机即可，拍摄场景就是家里、电影院和回家路上的便利店，无额外支出。\", \"hook\": \"“全网都在骂《牛来》，但我室友刚才在片尾哭到隐形眼镜移位。他说：你们中国人为什么总是用‘牺牲’来表达爱？”\", \"why_different\": \"别人蹭热点是骂或夸，我用外国人的眼泪制造认知反差，把网络骂声变成一场文化观察，深度感拉满且不站队。\"}, {\"title\": \"全网差评2.8的《牛来》，我们拿外国室友当人体情绪检测机\", \"angle\": \"把观影变成一次“反套路测评实验”：提前摘录豆瓣差评，比如“强行煽情”“逻辑崩塌”，然后带着没看过任何评论的外国室友入场，实时记录他会因为哪些桥段有反应，散场后逐条对照差评验证“谁在说谎”。\", \"audience\": \"爱看reaction、综艺式实验和影视吐槽区的乐子人观众，不一定看过《牛来》，但喜欢看不同观点碰。\", \"cost\": \"中：需要准备打印出来的差评卡片、计时器、情绪记录板；后期需要做分屏和对比字幕，剪辑时间比普通vlog多一倍。\", \"hook\": \"“今天我们要做全网最叛逆的测——评。准备好，室友每哭一次，我就划掉一条豆瓣差评。”\", \"why_different\": \"把主观观后感做成可互动的对照实验，用“泪点打卡”去验证争议点，既有吐槽区的玩梗属性，又有生活区的人情味，结构新颖。\"}, {\"title\": \"我把外国室友丢进《牛来》散场人群，数了数谁真的红了眼睛\", \"angle\": \"不只在私人观影反应上做文章，而是把事件放到公共空间：选一个人流量大的热门场次，带外国室友观影后，顺手在散场出口拦住陌生人问“你哭了吗”，把他一个人哭的画面和十位路人的嘴硬现场剪在一起，形成“个体情绪 vs 群体表达”的生活切片。\", \"audience\": \"泛生活区观众，喜欢街头采访、偶遇惊喜和人群观察的粉丝，以及关注“中国人真实观影反应”的吃瓜路人。\", \"cost\": \"较高：需要至少双机位（跟拍室友+抓拍路人），提前沟通影院和路人，散场时间窗口很短，可能要多跑几场；交通和人力成本高。\", \"hook\": \"“电影散场，我室友是唯一哭到鼻头红的人吗？我们蹲在门口，决定拦住每个出来的观众问一句——你刚才哭了吧？”\", \"why_different\": \"从“一人看哭”升级到“一群人的表情统计”，把网红电影的争议变成街头社会实验，素材充满不可复制的偶遇感，观众期待路人的真实反应和意外反转。\"}]', NULL, '2026-08-24 08:06:26', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (5, 5, 3, '我带着外国室友去看了全网骂的《牛来》，他居然被感动哭了？', '[{\"title\": \"带外国室友看《牛来》他哭了，我却笑死在影院 | 跨文化观察\", \"angle\": \"从“外国人的眼泪”切入，不聊电影技术，只聊文化情绪：为什么一个中国观众觉得烂的故事，会让外国人感到共鸣？以采访+聊天形式，拆解“泪点”背后的成长背景差异。\", \"audience\": \"喜欢跨文化对比、海外生活、留学生话题的B站用户，以及被《牛来》争议吸引的路人。\", \"cost\": \"低成本：手机拍摄，在家或咖啡厅聊天，不需要影院素材；需要外国室友出镜+字幕翻译。\", \"hook\": \"我带着我美国室友去看了全网都在骂的《牛来》，电影还没结束，我转头发现他哭到肩膀在抖。\", \"why_different\": \"别人都在骂电影，我却把镜头对准“被感动”的外国人，用他的眼泪反衬出我们吐槽背后的文化预设，情绪反转更强。\"}, {\"title\": \"全网差评《牛来》？我让外国室友盲猜评分，结果他给了9分\", \"angle\": \"做成“盲测/实验型vlog”：不让室友看任何评论，直接进影院看，记录他观前预期、观中微表情、观后评分，再与豆瓣评分对比，制造数据反差。\", \"audience\": \"日常vlog粉丝、reaction爱好者、爱看真实反应的观众，尤其喜欢根据弹幕投票互动的用户。\", \"cost\": \"中等成本：电影票+便携稳定器+手机或相机，需要设计“盲测”环节，后期加字幕、评分弹幕特效。\", \"hook\": \"我室友看完《牛来》后，激动地打出了9分，而我手机上的豆瓣评分是3.8——他以为我骗他。\", \"why_different\": \"用“盲评实验”制造悬念，观众会跟着猜室友的评分，结尾再引爆中外口碑落差，互动感比单纯吐槽更强。\"}, {\"title\": \"我开了一场《牛来》迷你放映会，外国室友和中国朋友吵起来了\", \"angle\": \"把个人围观升级为小群体“文化圆桌”：邀请外国室友+两位中国朋友共同观影，然后围绕“你觉得烂还是好”现场争论，用朋友间的真实冲突呈现中外审美差异。\", \"audience\": \"喜欢群像、社交观察、观点碰撞的年轻观众，适合B站“社交实验”类内容粉丝，也能吸引英文学习/跨文化讨论群体。\", \"cost\": \"较高成本：需要包场或家庭影院准备、至少两台录制设备+麦克风、朋友时间协调、后期剪辑量较大（多线叙事+字幕）。\", \"hook\": \"我只想带室友看个电影，没想到他和我中国朋友吵起来了，《牛来》到底该给几分？\", \"why_different\": \"从“一对一带看”升级为“多方观点对撞”，用综艺感的吵架现场替代个人感悟，话题讨论更立体，也更容易引发弹幕站队。\"}]', NULL, '2026-08-24 08:29:42', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (6, 1, 2, '想拍安福路', '[{\"title\": \"安福路brunch排队2小时实测：值不值？附避坑点单\", \"angle\": \"单店五维实测：排队耗时、出餐速度、口味、环境、性价比，用证据链给出明确结论和点单建议。\", \"audience\": \"第一次想去安福路打卡、怕踩雷的年轻人/游客。\", \"cost\": \"低：单店1次，约3小时，人均150元。\", \"hook\": \"这家店评分4.6，排队2小时，人均150，我的结论：不值得专门跑。别信评分，信我，后面有完整数据。\", \"why_different\": \"最轻量单店实测，直接回答‘值不值’，成本最低，适合日更快速产出；另两个分别聚焦多店横评和排队周期，体感完全不同。\"}, {\"title\": \"安福路3家网红brunch横评：我花了620元，最好吃的是评分最低那家\", \"angle\": \"同一条路3家店横向对比，用价格、等位时间、出片率、口味四个维度做数据表，最后按场景给推荐。\", \"audience\": \"有选择困难、周末聚餐聚会、想拍照但更看重口味的年轻人。\", \"cost\": \"中：3家店，分3天拍摄，总预算约700元。\", \"hook\": \"人均120，我点了三家招牌：班尼迪克蛋甜到齁，第二家等位50分钟，第三家评分最低但牛排汁水最足。最值那家，出乎意料。\", \"why_different\": \"从单店‘值不值’升级为多店‘选哪家’，用横评数据建立决策坐标，拍摄成本中等，适合周末档；与另两个形成单点、多点、时间线的三层视角。\"}, {\"title\": \"蹲点安福路5家brunch一周，我找到不用排队的3个时间段\", \"angle\": \"长周期排队观察：记录工作日vs周末、早中晚不同时段等位人数与出餐速度，总结错峰攻略并顺测人气款。\", \"audience\": \"时间敏感、讨厌排队的上班族和学生党，偏好效率导向的工具型内容。\", \"cost\": \"高：5家店，工作日+周末共2周踩点，自费预算1200元以上。\", \"hook\": \"我自费1200块，带秒表蹲了安福路5家brunch，每天记录10个整点的排队人数。结论：下午2点后人少一半，周三上午不用排队。具体方法在视频里。\", \"why_different\": \"切入‘排队策略’而非口味，用周期采样建立时间表，成本最高，属于30%周期对比选题；与单店实测、横评形成明显差异，能沉淀为避坑工具内容。\"}]', NULL, '2026-08-24 08:47:46', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (7, 5, 6, '应该怎么做', '[{\"title\": \"带狗排3小时，进店10分钟值得吗\", \"angle\": \"以宠物实际体验为核心，测评快闪店排队性价比与踩雷点，给出养宠人购物建议\", \"audience\": \"养宠人群，尤其爱买宠物用品但怕被网红店坑的年轻人\", \"cost\": \"低，自备宠物、交通费与店内消费，实拍排队和进店全程\", \"hook\": \"3小时排队换10分钟购物，我家狗子都不乐意了！\", \"why_different\": \"从宠物体验感切入，不只讲人，还看狗狗反应，测评更接地气\"}, {\"title\": \"3小时买买买，不如陪它们10分钟\", \"angle\": \"对比快闪店排队与隔壁领养活动冷清，探讨流量与生命价值的错位\", \"audience\": \"关注流浪动物、社会议题的泛年轻人，不局限养宠人群\", \"cost\": \"低，拍摄排队人流与邻近的流浪动物领养点，不需进店消费\", \"hook\": \"这里排3小时买猫狗零食，隔壁笼子里等了一下午没人要。\", \"why_different\": \"将消费主义与救助现实并置，用真实反差引发讨论，符合UP主救助科普定位\"}, {\"title\": \"流浪狗排队3小时，会被赶出去吗？\", \"angle\": \"带一只曾经被遗弃的流浪狗去快闪店，测店家是否真对宠物友好，展现动物尊严\", \"audience\": \"动物福利关注者与路人，爱看社会实验的B站用户\", \"cost\": \"中等，需救助犬配合，可能要协调店铺拍摄，准备应急用品\", \"hook\": \"我带刚救的流浪狗排队3小时，保安却让我滚出去。\", \"why_different\": \"用流浪狗的经历切“宠物友好”伪命题，有情绪张力但守住科普底线\"}]', 0, '2026-08-24 11:42:05', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (8, 5, 6, '实测上海快闪店排队3小时值不值', '[{\"title\": \"带宠排队3小时实测\", \"angle\": \"从宠物体验角度测评上海宠物友好快闪店，以宠物状态判断排队值不值，为养宠人避坑。\", \"audience\": \"爱带宠物出门的年轻养宠人，担心宠物受委屈，想找宠物友好去处。\", \"cost\": \"高：需筛选允许宠物的快闪店，含宠物交通和门票约800元。\", \"hook\": \"狗热趴地，前面还有50人，排不排？\", \"why_different\": \"首个从宠物体验角度测快闪店，宠物状态说话，不吹不黑。\"}, {\"title\": \"为猫排三小时，值！\", \"angle\": \"自费排队买网红快闪限定品，转卖或义卖，用排队时长换流浪猫口粮，反差引发共鸣。\", \"audience\": \"关注流浪动物、喜欢治愈视频的年轻人，愿意为善意停留三分钟。\", \"cost\": \"低：自费购买限定价约200元，义卖全捐，无场地费。\", \"hook\": \"凌晨四点排队，前面突然插队，为了猫，我忍了。\", \"why_different\": \"把无意义的消费排队变成救助公益，结尾公布义卖捐款明细。\"}, {\"title\": \"猫等零食，人排队三小时\", \"angle\": \"在快闪店排队现场采集人类等待行为，再用宠物延时满足实验对照，科普排队心理。\", \"audience\": \"对心理学和动物行为好奇的B站学生、职场人，喜欢硬核科普但不想枯燥。\", \"cost\": \"中：现场排队约两小时，宠物零食道具约300元。\", \"hook\": \"猫疯狂扒手也要吃，我偏不给——等三秒才能吃，人却排队三小时？\", \"why_different\": \"用宠物实验解释人类排队心理，双线叙事，科普不枯燥。\"}]', NULL, '2026-08-24 12:14:28', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (9, 2, 14, '拆解菲尔兹奖得主邓煜专访', '[{\"title\": \"专访里没说的数学真相\", \"angle\": \"从专访原文逐句对比官方通稿，找出被删减的争议观点。\", \"audience\": \"数学系学生、科研工作者、硬核科普爱好者。\", \"cost\": \"仅需资料收集和剪辑，几乎零成本。\", \"hook\": \"你以为邓煜只是谦虚？官方通稿删掉了最狠的一句。\", \"why_different\": \"不吹捧，用原文和通稿逐条对峙，呈现学术圈真实生态。\"}, {\"title\": \"通稿如何“杀死”一篇专访\", \"angle\": \"从新闻生产角度，分析官方通稿和专访的报道框架差异。\", \"audience\": \"新闻传播学子和新媒体小编。\", \"cost\": \"需要制作对比图表，素材购买，约几百元。\", \"hook\": \"同一篇专访，官方通稿和原始采访竟然是两个故事？\", \"why_different\": \"拆解媒体删改逻辑，教观众读出通稿背后的潜台词。\"}, {\"title\": \"菲尔兹奖背后的一路逆袭\", \"angle\": \"按时间线重述邓煜从少年到获奖的关键人生节点，讲成长故事。\", \"audience\": \"大学生、考研党、职场焦虑人群。\", \"cost\": \"需外出拍摄城市空镜、校园补拍，预算千元级。\", \"hook\": \"他拿奖前曾被导师断言“不适合做数学”，凭什么翻盘？\", \"why_different\": \"不聊奖本身，用人物传记剪辑手法，让人代入自己的困境。\"}]', 0, '2026-08-24 13:10:30', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (10, 5, 16, '解析Cursor多文件编辑更新', '[{\"title\": \"凌晨监控猫跑酷真相\", \"angle\": \"用监控录像拆解猫夜间活动规律，回应“猫为什么半夜疯跑”\", \"audience\": \"养猫新手+云吸猫年轻人，对猫作息好奇\", \"cost\": \"手机/家用监控拍一晚，剪辑2小时，几乎零成本\", \"hook\": \"凌晨两点，我的猫在墙上飞，碗里还有粮——它到底在干嘛？\", \"why_different\": \"不摆拍，用真实监控回放+行为学解读，给出三个可验证结论\"}, {\"title\": \"口炎流浪猫拔牙日记\", \"angle\": \"记录救助一只口炎流浪猫的检查、手术与恢复过程，讲科学护理\", \"audience\": \"关注救助、有领养意向的中青年观众\", \"cost\": \"联系救助站+跟随送医，约3天，医疗费可拍进账单\", \"hook\": \"一只流口水吃不下饭的流浪猫，医生说可能得拔光所有牙——救不救？\", \"why_different\": \"不止煽情，拍清每笔花费和护理步骤，罕见但克制\"}, {\"title\": \"五款猫粮配料表测评\", \"angle\": \"从配料表前五行和营养成分对比平价猫粮，教新手避开淀粉陷阱\", \"audience\": \"新手养猫/准备换粮的年轻人，预算有限但想选好粮\", \"cost\": \"买5款试吃装+打印配料表，约200元，2天可完成\", \"hook\": \"同样200元猫粮，有的第一行是鸡肉，有的第一行是玉米——你选哪个？\", \"why_different\": \"拿实物横评，单条视频给出可直接照抄的选粮公式\"}]', NULL, '2026-08-24 14:07:14', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (11, 5, 7, '暂不纳入宠物频道选题', '[{\"title\": \"24小时偷拍猫，发现它根本没睡觉\", \"angle\": \"用监控+手持镜头还原猫咪真实作息，打破“猫整天睡觉”刻板印象，穿插行为解读\", \"audience\": \"云吸猫但没养过猫的年轻人，喜欢看猫发呆、打闹和睡觉\", \"cost\": \"手机+家用摄像头，拍1天剪1天，两天完成，零额外支出\", \"hook\": \"都说猫一天睡16小时，我盯着监控看了24小时，发现事情不对劲……\", \"why_different\": \"不摆拍，用事实数据展示猫的作息，顺带科普猫睡眠习惯\"}, {\"title\": \"被弃养的加菲猫，我帮它找家\", \"angle\": \"记录救助一只被遗弃加菲猫的过程：体检、找领养、谈心，强调领养代替购买和科学饲养\", \"audience\": \"想养猫但纠结买还是领养的年轻人，以及关心流浪动物的人\", \"cost\": \"体检+寄养约几百元，6天素材拆3期短篇，单期制作1天\", \"hook\": \"这只猫被主人扔在公司楼下，路过三天没人管，我决定帮它找个家……\", \"why_different\": \"真实救助全程无摆拍，把“领养代替购买”落到具体行动，并给筛选领养人实操方法\"}, {\"title\": \"宠物零食测评：5款冻干避坑\", \"angle\": \"自费购买5款常见宠物冻干，从配料表、适口性、复水实验三维度真实测评，不恰饭\", \"audience\": \"正在给猫狗选零食的新手铲屎官，怕买到添加剂太多的\", \"cost\": \"5款冻干约200元，一天拍素材一天剪辑，两天完成\", \"hook\": \"我买了5款宠物冻干，看完配料表，直接想扔进垃圾桶。\", \"why_different\": \"纯自费无广，用成分和实验说话，教观众看懂配料表，避开广告陷阱\"}]', NULL, '2026-08-25 06:09:21', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (12, 11, 15, '实测上海快闪店值不值得排队', '[{\"title\": \"把快闪店当电影骂\", \"angle\": \"用影评人拉片方法实地测评一家影视IP快闪店，评动线、道具、氛围，不评商品。\", \"audience\": \"怕踩雷、想找周末解闷的新片影迷\", \"cost\": \"上海单店拍摄1天+剪辑1天，总计2天，成本低\", \"hook\": \"我用影评人的分镜表实测这家快闪店，发现它的“高潮”只有8分钟，其余全靠排队硬撑。\", \"why_different\": \"把探店变成拉片，用影评理论回答值不值，回归频道影视解读定位。\"}, {\"title\": \"影视IP快闪店福利还是镰刀\", \"angle\": \"从授权、定价、联名机制拆解影视IP快闪店，回答粉丝福利还是商业镰刀。\", \"audience\": \"关注IP消费、想看懂衍生品逻辑的影迷\", \"cost\": \"资料收集2天，走访2店1天，3天内完成，成本中\", \"hook\": \"同款IP联名T恤快闪店贵3倍，店员却说卖的是“氛围税”——这家店到底在卖什么？\", \"why_different\": \"不探店体验，直击产业链，用数据回答值不值，知识密度更高。\"}, {\"title\": \"电影是怎么骗你排队的\", \"angle\": \"从影史排队长镜头切入，拆解排队背后的心理操控，反照上海快闪店现象。\", \"audience\": \"对电影叙事和社会心理感兴趣的深度影迷\", \"cost\": \"不实拍，用授权短片段和图集剪辑，1-2天内完成，成本最低\", \"hook\": \"《肖申克的救赎》里排队领饭的镜头，和快闪店门口排队的表情一模一样，让我怀疑导演早看透了排队。\", \"why_different\": \"完全绕开消费测评，用影像分析解释排队心理，是三种里最不依赖现场的小众影评。\"}]', NULL, '2026-08-25 06:54:53', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (13, 5, 16, '111111', '[{\"title\": \"宠物乱改文件？实测翻车现场\", \"angle\": \"拿宠物捣乱电脑的日常，类比多文件编辑的混乱，用动物行为科普收尾\", \"audience\": \"养宠又爱折腾电脑的年轻人，喜欢搞笑+轻科普\", \"cost\": \"手机拍摄+已有素材，0元，1天内完成\", \"hook\": \"我家猫刚刚把我三个文件改坏了，这波操作你给几分？\", \"why_different\": \"用宠物拆家类比技术混乱，治愈搞笑中带严谨科普\"}, {\"title\": \"救助站猫狗的多文件协作实验\", \"angle\": \"记录救助站多只宠物协同完成取食任务，类比多文件并行编辑的协作逻辑\", \"audience\": \"关注流浪动物救助、爱看团队协作故事的云养宠观众\", \"cost\": \"需联系救助站，交通+小零食道具，约200元，1天拍摄\", \"hook\": \"三个文件同时改会崩，五只猫同时抢饭会怎样？\", \"why_different\": \"把技术概念翻译成救助站真实行为观察，科普与暖心并存\"}, {\"title\": \"智能喂食器多文件编辑避坑指南\", \"angle\": \"测评多款智能喂食器的多宠物识别功能，类比多文件编辑的冲突处理\", \"audience\": \"想买智能宠物用品、怕踩坑的年轻养宠人\", \"cost\": \"借测产品+家中拍摄，0元到100元，2-3天完成\", \"hook\": \"多宠物识别就像多文件编辑，我家两只猫已经吵翻天了\", \"why_different\": \"用品测评套用技术逻辑，理性给结论，补足B站同类内容深度\"}]', NULL, '2026-08-25 06:55:21', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (14, 5, 21, '对比中美超市100元购买力', '[{\"title\": \"100元猫粮测评：穷养不丢人\", \"angle\": \"测评100元档猫粮的配料与安全底线，用真买真拆回应新手选粮焦虑\", \"audience\": \"新手铲屎官、预算有限但想科学养宠的年轻人\", \"cost\": \"猫粮样品约100-200元，1天内拍完\", \"hook\": \"100块在猫粮界是青铜还是王者？这期用配料表说人话。\", \"why_different\": \"不云评粮，真买真拆真算账，对标新手选粮焦虑\"}, {\"title\": \"100元救活一只流浪猫？\", \"angle\": \"跟拍一次真实流浪猫救助，记录100元预算内的送医、清创与安置流程\", \"audience\": \"云吸猫爱心观众、可能参与救助的城市青年\", \"cost\": \"真实救助开销约100元起步，1天内拍完\", \"hook\": \"遇到被弃养的猫，100块能救到什么程度？跟我走一遍。\", \"why_different\": \"真实救助过程全记录，不摆拍不煽情，花多少报多少\"}, {\"title\": \"100元在不同城市养猫，差多少？\", \"angle\": \"对比不同城市100元的养宠采购清单，算清城市差异下的养宠成本\", \"audience\": \"准备养宠但纠结预算、在意城市开销的年轻人\", \"cost\": \"跨城素材征集或本地多场景拍摄，2-3天完成\", \"hook\": \"同样100块，在北上广和县城能买到的养宠生活差多少？\", \"why_different\": \"把地域消费差异落到养宠实操，解决城市青年养宠焦虑\"}]', NULL, '2026-08-26 12:00:52', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (15, 5, 21, '对比中美超市100元购买力', '[{\"title\": \"100元，中外救助站买了啥？\", \"angle\": \"以救助站采购视角，用100元在中国宠物店和美国超市对比救助粮/猫砂价格重量，破除“没钱别救助”\", \"audience\": \"想捐款但怕钱打水漂的云救助年轻人\", \"cost\": \"本地超市采购+美国线上价格截图，1天拍剪，花费约100元\", \"hook\": \"救助站阿姨说100元不够买桶猫奶粉，我偏要拖回一购物车宠物粮\", \"why_different\": \"不是测评零食，而是按救助站真实采购清单逐项算克价，让善意有标尺\"}, {\"title\": \"100元养猫3天，中美花费差多少？\", \"angle\": \"中国用100元、美国用14美元等值金额，分别为猫配3天饮食，记录进食、便便和体重变化\", \"audience\": \"预算有限却不想委屈猫的年轻养宠人\", \"cost\": \"3天连续记录+采购约100元，美国价格用官方渠道折算对比\", \"hook\": \"我家猫一碗冻干80元，现在100元要撑3天？我直接立下flag\", \"why_different\": \"用猫的进食量和便便状态反馈性价比，演示便宜粮也能科学选\"}, {\"title\": \"100元中美宠物医院能干啥？\", \"angle\": \"对比中美宠物医院里100元/14美元能做的检查项目，现场咨询兽医，整理小病就医切入口\", \"audience\": \"怕医院乱收费、总想自己硬扛的新手养猫人\", \"cost\": \"联系宠物医院拍视诊+美国价目表素材，约2天完成，挂号费100元\", \"hook\": \"医生说要先交500元查血，我掏出100元问：这些够做哪些？他愣了一下\", \"why_different\": \"直接把医院价目表拍下来，对比两国小病检查门槛，教你不花冤枉钱\"}]', NULL, '2026-08-26 12:09:50', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (16, 5, 10, 'test', '[{\"title\": \"猫咪拆家全记录？错！是监控真相\", \"angle\": \"用监控视角还原猫半夜搞破坏的完整逻辑链，打破“猫坏”刻板印象\", \"audience\": \"喜欢云吸猫、养猫的18-30岁年轻人\", \"cost\": \"家用监控+手机剪辑，几乎零成本\", \"hook\": \"凌晨三点猫精准推下杯子，监控拍到的“犯罪现场”另有隐情？\", \"why_different\": \"首次用监控“推理”猫行为，既有趣又科普动物本能\"}, {\"title\": \"救助一只被遗弃的怀孕猫，结局反转\", \"angle\": \"记录救助怀孕流浪猫到生产全过程，穿插科学喂养和引产绝育科普\", \"audience\": \"关注流浪动物、想云救助的年轻女性为主\", \"cost\": \"车费+猫粮猫砂+兽医检查，约500元内\", \"hook\": \"打开纸箱那一刻，里面不是丢的猫，是三只刚睁眼的小奶猫……\", \"why_different\": \"不刻意煽情，用“科学救助”每一步决策展示负责任养宠\"}, {\"title\": \"花5000块给猫做行为矫正，值不值？\", \"angle\": \"以高价请宠物行为专家上门改造“问题猫”为线索，探讨养宠消费观和科学行为学\", \"audience\": \"养猫遇到行为问题、愿意为宠物花钱的都市白领\", \"cost\": \"行为专家上门费+道具+拍摄人工，约5000元（可拆成系列）\", \"hook\": \"“我家猫乱尿一年，我花五千块请专家上门，结果被说不是猫的错？”\", \"why_different\": \"直面敏感消费话题，用实际案例拆解“问题宠物”背后的误读\"}]', NULL, '2026-08-26 12:33:02', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (17, 5, 10, 'test', '[{\"title\": \"用零食迷宫测猫狗智商\", \"angle\": \"用零食迷宫实验展示猫狗认知差异，请训练师短评，科普本能与智商\", \"audience\": \"云吸猫狗的年轻人，爱看轻松有梗的日常，想了解宠物行为\", \"cost\": \"手机+家里道具，零额外费用，1天拍剪\", \"hook\": \"都说猫更聪明，我用零食迷宫测了五只猫狗，结果崩溃…\", \"why_different\": \"门槛最低、可复制性强，把口水战变成可视零食实验\"}, {\"title\": \"它还能再相信人类吗\", \"angle\": \"记录流浪猫从警惕到接受触碰的社会化过程，科普救助中的安全操作与情绪边界\", \"audience\": \"关注流浪猫救助、有爱心但怕被抓的年轻人\", \"cost\": \"隔离笼+手套等基础物资，约200元，3天拍剪\", \"hook\": \"打开笼子，流浪猫全身炸毛对我嘶吼，我要用三天测试它能否重新信任人\", \"why_different\": \"把救助故事变成行为观察实验，情感张力与科学方法并重\"}, {\"title\": \"猫咪认主实验辟谣\", \"angle\": \"设计无伤害对照实验，观察猫咪对陌生人/主人的反应，请专家结论辟谣养不熟\", \"audience\": \"新手猫奴和纠结‘猫养不熟’的家长，要数据不要玄学\", \"cost\": \"猫咖合作+专家咨询，约800元，拍2天剪1天\", \"hook\": \"全网说猫只认一个主人，我设计了个实验，结果所有猫都…\", \"why_different\": \"硬核实验打脸偏见，有权威佐证，适合深度科普片\"}]', NULL, '2026-08-26 12:34:08', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (18, 5, 10, 'test', '[{\"title\": \"别信网红宠物测试\", \"angle\": \"用自家猫实测网上流传的宠物性格测试，科普其不科学性\", \"audience\": \"养猫但容易被情绪类测试带偏的年轻宠物主\", \"cost\": \"零成本，手机拍自家猫+查权威文献资料即可\", \"hook\": \"我问它愿不愿意被摸，它给了我一爪子——测试结果说这算\'高冷\'？\", \"why_different\": \"从辟谣角度做宠物测试，低成本快节奏，适合3天内产出\"}, {\"title\": \"流浪猫警惕性测试\", \"angle\": \"参与救助站的流浪猫，测试不同猫对陌生人的反应，引出TNR和领养\", \"audience\": \"云吸猫狗、想参与救助但没空实际动手的城市年轻人\", \"cost\": \"跟拍救助站半天，路费+少量猫罐头\", \"hook\": \"我把手伸进笼子，三只流浪猫反应完全不同，最凶的那只居然最黏人\", \"why_different\": \"测试对象换成流浪动物，把救助科普融入互动，刷云养猫好感\"}, {\"title\": \"猫条测评方法翻车\", \"angle\": \"复测某热门猫条测评视频的测试法，结果和结论完全不同，讲如何科学选零食\", \"audience\": \"爱看宠物测评、为自家主子买买买的养猫年轻人\", \"cost\": \"购买5款常见猫条约100元，在家拍摄试吃过程\", \"hook\": \"全网都用\'先闻后吃\'测猫条，我照做后猫咪直接走开——结论和网上完全相反\", \"why_different\": \"从测评方法本身切入，揭示逻辑漏洞，成本中等但单期可控\"}]', NULL, '2026-08-26 12:45:39', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (19, 5, 10, 'test', '[{\"title\": \"猫弄倒花瓶装瘸\", \"angle\": \"日常记录：实拍猫咪闯祸后装瘸全过程，捕捉反转瞬间。\", \"audience\": \"云吸猫年轻人，喜欢看猫犯错后心虚反应。\", \"cost\": \"手机实拍+家中场景，约0元。\", \"hook\": \"花瓶倒下一秒，猫突然抬前腿装瘸，我该骂还是该抱？\", \"why_different\": \"真实日常无摆拍，用冲突开场留住人，结尾留互动话题。\"}, {\"title\": \"垃圾桶捡到未睁眼奶猫\", \"angle\": \"救助故事：雨天垃圾桶旁纸箱里四只奶猫，记录送医和喂养。\", \"audience\": \"关心流浪动物、愿意云救助的年轻观众。\", \"cost\": \"外出拍摄+基础体检，约200-500元。\", \"hook\": \"雨天垃圾桶旁纸箱在动，打开是四只没睁眼的奶猫在发抖。\", \"why_different\": \"真实救助过程+领养代替购买科普，不卖惨只给方法。\"}, {\"title\": \"狗剃光毛更热\", \"angle\": \"养宠科普：夏天给狗剃光毛的误区，用兽医口播和对比实验讲清。\", \"audience\": \"新手养狗人，担心宠物中暑又不懂毛发作用。\", \"cost\": \"棚拍口播+资料图，约0-100元。\", \"hook\": \"主人把狗毛剃光，狗躲在床底不出，兽医却说这样更热。\", \"why_different\": \"纠正常见误区，给出科学依据和可操作建议，不空谈。\"}]', NULL, '2026-08-26 12:47:35', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (20, 5, 10, 'test', '[{\"title\": \"猫咪智商测试翻车\", \"angle\": \"用6个家庭小挑战测猫解决问题能力，边测边讲猫咪行为学。\", \"audience\": \"云吸猫的学生和租房青年，想看萌宠又好奇猫智力。\", \"cost\": \"手机加纸杯、冻干等道具，半天拍完。\", \"hook\": \"冻干扣在杯子下，猫扒拉3下就摆烂，镜头怼脸：它笨还是懒？\", \"why_different\": \"把测试娱乐化但不误导，给行为学依据，低成本日常。\"}, {\"title\": \"救回躲人奶狗做测试\", \"angle\": \"对刚救助的流浪狗做温和社会化观察，记录它从躲人到主动靠近。\", \"audience\": \"关注流浪救助、可能领养的青年，想了解狗能否进家。\", \"cost\": \"需1-2天跟拍救援与行为观察，基础牵引绳和厚手套。\", \"hook\": \"刚救回的狗见手就缩，志愿者戴上厚手套慢慢伸过去，它抖了一下。\", \"why_different\": \"真实救助结合行为测试，不摆拍不伤害，给领养评估参考。\"}, {\"title\": \"领养资格30题自测\", \"angle\": \"用30道领养自测题拆解住房、时间、预算、医疗责任，附兽医建议。\", \"audience\": \"想领养但怕踩坑的新手，以及被退养劝退的犹豫党。\", \"cost\": \"请兽医或收容所远程连线，配图表题板，约1天拍剪。\", \"hook\": \"一张被退回的领养申请表甩在桌上：你的居住条件不适合养狗？\", \"why_different\": \"把领养门槛讲清，不劝退不违规，评论区按题答疑给依据。\"}]', NULL, '2026-08-26 12:48:58', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (21, 5, 10, 'test', '[{\"title\": \"猫反应测试翻车现场\", \"angle\": \"用家庭常见小道具测试猫反应，记录治愈反差瞬间，科普猫行为。\", \"audience\": \"云吸猫年轻观众，想看猫真实反应和行为解读。\", \"cost\": \"手机室内拍摄，道具零成本，1天完成。\", \"hook\": \"测试猫智商？道具刚放好，猫一巴掌拍飞，还回头瞪我。\", \"why_different\": \"不做AI工具，切入宠物行为观察，低门槛真实治愈。\"}, {\"title\": \"领养前性格测试\", \"angle\": \"记录待领养狗从躲人到亲近的测试过程，展示领养匹配方法。\", \"audience\": \"潜在领养人、关注流浪动物救助的年轻观众。\", \"cost\": \"与救助站合作跟拍半天，需沟通和交通，约2天。\", \"hook\": \"第一次见面它缩在角落不敢动，15分钟后主动蹭我手。\", \"why_different\": \"救助实拍+领养匹配科普，推动领养代替购买。\"}, {\"title\": \"家庭安全测试：猫别碰\", \"angle\": \"用安全对照展示猫对常见物品反应，科普家庭隐患，避免误食。\", \"audience\": \"新手养猫人、理性科学饲养的年轻观众。\", \"cost\": \"室内准备安全物品和资料，查兽医建议，拍摄1-2天。\", \"hook\": \"猫薄荷和葱摆一起，猫先吃葱？这动作很危险。\", \"why_different\": \"科学饲养+安全避险，用对照测试替代AI工具，实用性强。\"}]', NULL, '2026-08-26 12:57:18', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (22, 5, 10, 'test', '[{\"title\": \"给狗做智商测试翻车了\", \"angle\": \"用网红狗智商测试题给自家狗实测，穿插兽医解读测试设计缺陷，避免智商焦虑。\", \"audience\": \"想判断自家狗聪明与否的新手养狗人和云吸狗观众。\", \"cost\": \"居家拍摄，道具为日常零食玩具，零额外成本，3天内完成。\", \"hook\": \"都说边牧是狗界博士，我家的却连握手都学不会，今天用6道题测它到底是不是智商欠费。\", \"why_different\": \"不吹测试权威性，用兽医视角解释行为测试的误差，反智商焦虑。\"}, {\"title\": \"流浪猫体检惊魂2小时\", \"angle\": \"记录流浪猫从捡到送医做猫瘟、血常规等基础检查，拆解救助第一步该怎么走。\", \"audience\": \"关注流浪动物救助、准备第一次捡猫的年轻观众。\", \"cost\": \"需与宠物医院沟通拍摄一次基础体检，成本低，剪辑1天。\", \"hook\": \"捡到一只浑身湿透的小猫，医生说再晚两小时就没了，第一项测试结果让我腿软。\", \"why_different\": \"真实救助过程+兽医科普体检指标，把情绪和科学流程结合。\"}, {\"title\": \"猫狗禁忌食物辟谣测试\", \"angle\": \"盘点猫狗常见致命食物，用安全道具和文献结论逐一辟谣，不实拍喂食。\", \"audience\": \"养宠小白与爱看辟谣科普的云吸猫狗人群。\", \"cost\": \"室内表格+实物道具拍摄，无真实喂食，零成本，2天完成。\", \"hook\": \"全网都说猫喝牛奶会死，但多少量才会出事？我用一张表把常见‘致命食物’测明白了。\", \"why_different\": \"不实拍危险喂食，用文献和结论做硬核辟谣，避开博眼球伤害。\"}]', NULL, '2026-08-26 13:03:30', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (23, 15, 22, '测评不刷碗免煮速食一桶两吃', '[{\"title\": \"一件外套搞定通勤约会\", \"angle\": \"把速食一桶两吃转成穿搭一衣两穿，不买新衣，用衣柜现有外套给通勤和约会两套搭法。\", \"audience\": \"想少买衣服、怕买错基础款的穿搭新手女生。\", \"cost\": \"低：翻衣柜+对镜自拍，半天可完成。\", \"hook\": \"学完这期，你也能用一件外套直接切通勤和约会，不用早起换装。\", \"why_different\": \"真人上身对比两套穿搭，结论先行，不空谈搭配。\"}, {\"title\": \"平价三用盘上脸实测\", \"angle\": \"把一桶两吃转成美妆一物三用：买三盘平价唇颊眼多用盘，上脸测显色、持妆和是否闷痘。\", \"audience\": \"预算有限、怕买错的学生党/彩妆新手。\", \"cost\": \"中：购3款平价多用盘+上脸对比，1-2天拍完。\", \"hook\": \"结论先放：不是每盘都值得买；怕踩雷就看我上脸对比。\", \"why_different\": \"不吹多用途，按上课/通勤场景测真实妆效，给避坑结论。\"}, {\"title\": \"免打理神裤实穿测评\", \"angle\": \"把免煮概念转成免烫免打理：测三条号称不用熨的神裤，实穿一整天看久坐起皱和版型。\", \"audience\": \"经常久坐/出差、没时间熨衣服的上班族女生。\", \"cost\": \"中高：购3-4条裤子，外出实穿一天，2-3天完成。\", \"hook\": \"怕买错免打理神裤？我先替你穿一天，开头直接说哪条最值得留。\", \"why_different\": \"真人实穿一整天，用通勤久坐场景给对比，不空口说免烫。\"}]', NULL, '2026-08-26 13:36:23', NULL);
INSERT INTO `idea_sessions` (`id`, `user_id`, `topic_id`, `vague_idea`, `ideas_json`, `selected_index`, `created_at`, `saved_json`) VALUES (24, 15, 22, '测评不刷碗免煮速食一桶两吃', '[{\"title\": \"一衣两穿懒人通勤实测\", \"angle\": \"把“一桶两吃”转成一件单品两种通勤约会穿搭，真人上身对比实穿效果\", \"audience\": \"怕麻烦、想一件衣服多场景穿的通勤年轻人\", \"cost\": \"现有衣柜单品+手机或相机室内试穿，3天内可完成\", \"hook\": \"学完这期，你能用一件衬衫搞定通勤和约会两套造型，不花冤枉钱\", \"why_different\": \"不照搬美食测评，只取一物两用概念，做时尚区真人上身对比\"}, {\"title\": \"开架一盘两用避坑\", \"angle\": \"把“一桶两吃”转成开架眼影盘兼腮红修容是否实用的上脸踩坑复盘\", \"audience\": \"预算有限、怕开架彩妆买错的学生党和新手\", \"cost\": \"自购3件百元内开架彩妆，室内上脸对比，3天内可完成\", \"hook\": \"怕买错的姐妹，这期帮你实测百元内一盘两用彩妆，值不值上脸见分晓\", \"why_different\": \"用踩坑复盘代替虚假种草，上脸实测开架盘两用是否智商税\"}, {\"title\": \"免烫衬衫懒人测评\", \"angle\": \"把“不刷碗免煮”转成免烫免打理衣物是否值得买的面料与上身效果测评\", \"audience\": \"住宿舍或常出差、不想熨烫衣服的懒人观众\", \"cost\": \"购入或借用3件免烫衬衫，室内与通勤实拍，3天内可完成\", \"hook\": \"看完这期，你买免烫衬衫前会先看面料标，少退三件货\", \"why_different\": \"从“免煮”提取“免打理”，做面料实测而不是纯搭配推荐\"}]', NULL, '2026-08-26 13:56:28', '[]');
INSERT INTO `scripts` (`id`, `user_id`, `topic_id`, `idea_session_id`, `outline`, `shot_list`, `comments_text`, `script_json`, `cover_prompts_json`, `risks_json`, `created_at`) VALUES (1, 1, 1, 3, '主题：上海户外潮流展值不值得去\n1. 开头抛冲突：展会门票贵，到底是内容还是拍照局\n2. 到达国家会展中心，记录动线、排队、第一印象\n3. 三个展位深度体验：好看但买不到 / 能试穿 / 有品牌活动\n4. 商业化机会：联名、探店、线下活动怎么接\n5. 结论：适合哪类 UP、怎么拍才不踩坑', '相机+手机、稳定器、收音麦、展会票、充电宝、名片、备用口播提纲', '- 求完整路线和票价，别只拍好看的部分。\n- 开头 10 秒不知道在讲什么，建议直接抛冲突。\n- 想看真实排队和踩坑，不要只有精修镜头。\n- 适合周末两个人去吗？预算大概多少？\n- 封面信息太满，标题党了但内容还行。\n- 弹幕都在问合作品牌，希望说清楚是不是广告。\n- 后半段节奏掉了，体验过程可以再拆细一点。\n- 如果有「值不值得去」的结论会更好。', '{\"title\": \"上海户外潮流展，我算了一笔账：值不值得去？\", \"hook\": \"129 块的门票，我排了快 20 分钟才进场。先说结论：上海户外潮流展，别为‘潮流’买单，要为‘你能试到和带走什么’买单。全程自费，没有品牌充值。\", \"duration_hint\": \"正片约 8 分 20 秒，卡在 9 分钟内，适合日更节奏\", \"shots\": [{\"time_range\": \"00:00-00:15\", \"camera\": \"手持正面近景，背景是会展中心入口，快速推进\", \"action\": \"举票对着镜头，另一只手按下计时器\", \"line\": \"129 块的门票，我排了快 20 分钟才进场。先说结论：上海户外潮流展，别为‘潮流’买单，要为‘你能试到和带走什么’买单。全程自费，没有品牌充值。\", \"interaction\": \"值不值得？弹幕先来一波 1 或 2。\"}, {\"time_range\": \"00:15-00:48\", \"camera\": \"GoPro 胸挂 POV 拍地铁到入口，切手机秒表特写\", \"action\": \"从地铁口一路走，指着指示牌，最后停在队列末尾\", \"line\": \"完整路线：2 号线徐泾东站 5 号口出，步行大概 8 分钟到展馆入口。别走 4 号口，那边在施工，绕路。我 10:02 到，排队到 10:21，20 分钟进场。票价工作日早鸟 89，现场 129，周末统一 129。\", \"interaction\": \"弹幕记一下：5 号口。后边我会把两人预算算给你。\"}, {\"time_range\": \"00:48-01:30\", \"camera\": \"广角环视场馆，后拉；再快速扫过打卡点\", \"action\": \"进馆后先快速走一圈，口播出现场画面\", \"line\": \"第一印象：确实出片，灯光、展位、模特都在线。但如果你只刷到精修图，会以为这个展很大。实际可逛的区域大概是三个馆，其中一半是品牌装置和打卡点。好看的部分我已经拍了，接下来带你去看被剪掉的部分。\", \"interaction\": \"想看真实排队的，把‘真实’打在公屏上。\"}, {\"time_range\": \"01:30-02:30\", \"camera\": \"跟拍排队，拍队伍长度；特写展位‘仅供展示’标签\", \"action\": \"站在某个展位前，拍产品，但指着不可购买说明牌\", \"line\": \"第一个深度展位：某品牌概念区。东西好看，但都是样品，不能买，不能试穿。工作人员说，要买请去线上。我来这里不是骂它，而是帮你算：这个展位你能带走的只有照片。所以如果你为了买装备来，这个区域可以直接跳过。品牌名我先打码——因为我跟他们没有合作关系，拍出来反而像广告。\", \"interaction\": \"有没有人遇到过‘好看但买不到’？弹幕举手。\"}, {\"time_range\": \"02:30-03:40\", \"camera\": \"中近景拍试穿；特写吊牌和尺码表；秒表计时\", \"action\": \"在第二个展位试穿冲锋衣，活动手臂，拍下价格标签\", \"line\": \"第二个：能试穿的户外品牌。排队 12 分钟，试穿 3 分钟，这是全馆唯一能让我把装备穿上身的展位。尺码不算全，热门款只有 M 和 L。建议穿修身衣服来，不然套不上。结论：如果你目标明确，可以冲；如果你只想闲逛，这 12 分钟排队不如去隔壁拿赠品。\", \"interaction\": \"三个礼物：能试穿、能买、能薅。你们最看重哪个？\"}, {\"time_range\": \"03:40-05:00\", \"camera\": \"快剪活动海报、集章卡、抽奖箱；特写兑奖规则\", \"action\": \"拍第三个展位的品牌活动，参与扫码集章，展示小礼品\", \"line\": \"第三个：有品牌活动的展位。我参加了扫码集章，排了 8 分钟，拿了一个帆布袋和一张咖啡券。福利是真的，但别被‘限量’催着跑。活动规则写的是‘先到先得’，我实际看到下午两点补货。所以正确的打开方式是：上午看展，下午蹲活动，人少而且奖品没发完。\", \"interaction\": \"拿到的在弹幕扣‘薅到’，没拿到的扣‘下次一定’。\"}, {\"time_range\": \"05:00-06:00\", \"camera\": \"中景，UP 坐在休息区，旁边摆着品牌周边\", \"action\": \"坐下来算账，展示小票和记账 App\", \"line\": \"如果你们是两个人周末去：门票 258，两杯水加简餐 80，地铁 30，合计 368。如果买装备，再加预算。我的建议是预算控制在 400 以内，因为现场没有价格优势，大部分品牌和线上同价，部分还更贵。\", \"interaction\": \"双人预算 400 内，你们觉得还能更低吗？\"}, {\"time_range\": \"06:00-07:00\", \"camera\": \"录屏展示剪辑软件，再切回实景\", \"action\": \"把之前拍的素材拖进剪辑软件，展示废片和删掉的排队画面\", \"line\": \"有人说后半段容易掉节奏，所以我故意把最无聊的等位、绕路、找不到入口都留着。因为它们才是这个展的真实组成部分。这也是我想做的体验派：不是镜头里的大片，而是你真正会遇到的流程。\", \"interaction\": \"想要我保留‘无聊但真实’的片段，扣 1；只要高能剪辑，扣 2。\"}, {\"time_range\": \"07:00-07:50\", \"camera\": \"站在场馆出口，背景人流，使用分屏字幕卡\", \"action\": \"总结三类人，分别给结论\", \"line\": \"最终结论：第一类，喜欢拍照、逛市集、收集周边的——可冲，早鸟票更划算。第二类，想认真买一件冲锋衣或帐篷的——可逛但别买，试完记货号线上蹲折扣。第三类，对排队零容忍、追求沉浸体验的——可避雷，这个展队伍的密度比内容密度高。\", \"interaction\": \"你是哪类？弹幕打‘冲’、‘逛’或‘避’。\"}, {\"time_range\": \"07:50-08:20\", \"camera\": \"正面近景，手势指向屏幕，字幕显示‘自费无广’声明\", \"action\": \"口播 CTA，指向评论区\", \"line\": \"如果你也想知道某个展或者店到底值不值得，把名字打在评论区，点赞最高的我下期去拆。我是体验派，不吹不黑，用脚和钱包投票。点个关注，我们评论区见。\", \"interaction\": \"三连可以指定下一期选题，不信你试试。\"}], \"cta\": \"这条视频如果能帮到你，点个三连。点赞过 5 万，我就把评论区点名最高的三个展/店做成下期实测——所以你想看哪家，直接打在评论区。\"}', '[{\"style\": \"电影感实拍海报\", \"prompt\": \"远景：上海国家会展中心四叶草建筑入口，一个穿黑色冲锋衣的年轻男子背对镜头，手举门票，面前是人流长队。低角度仰拍，阴天自然光，电影感青橙色调。顶部大字：上海户外潮流展值不值？底部小字：实测排队/票价/预算。画面干净，有冲击力。\"}, {\"style\": \"3D 渲染立体字海报\", \"prompt\": \"C4D 风格 3D 立体字‘值不值得？’占画面中央，字体上坐着露营小人。背景是展会帐篷、背包、登山鞋、排队号码牌漂浮。高饱和撞色，硬阴影，电商促销海报构图。\"}, {\"style\": \"手工拼贴杂志风\", \"prompt\": \"户外潮流展评测封面，剪纸拼贴风格：门票、计时器、排队小票、冲锋衣、帆布袋剪影层叠，中间手写中文标题‘算笔账’。复古纸质纹理，暖色调，胶片颗粒。\"}, {\"style\": \"对比分屏海报\", \"prompt\": \"左右分屏对比：左边精修网红打卡照，光线梦幻、人像精致；右边真实排队现场，面无表情的人群和长队。中间用粗线分割，顶部小字‘同一场展’，底部大字‘两种现场’。写实摄影，高细节。\"}, {\"style\": \"信息图表插画\", \"prompt\": \"极简扁平插画，中央是会展中心地图路线图，旁边标出 5 号口、排队位置、三个展位图标。用时间轴和价格标签组成视觉元素，顶部标题‘上海户外展避坑地图’。高对比色块，现代设计感。\"}, {\"style\": \"夸张漫画风\", \"prompt\": \"漫画分镜封面：主角高举计时器站在会展中心门口，旁边一个巨大的游标卡尺夹住‘潮流’二字。人物表情冷静，背景人群排队。粗线条美式漫画风格，红黄蓝高饱和，标题‘拆穿’大字。\"}]', '[{\"level\": \"high\", \"category\": \"夸大宣传\", \"detail\": \"标题和内容若使用‘拆穿’‘打脸’等词，容易让观众产生证据确凿的预期，但展会本身并无明确广告承诺，结论容易被认为是个人主观判定。\", \"suggestion\": \"用‘值不值得’‘算笔账’替代‘拆穿’，明确是本场自费体验样本，不对整个展会行业作结论。\"}, {\"level\": \"mid\", \"category\": \"未核实体验\", \"detail\": \"排队时长、票价、活动补货信息受时段和场次影响，若未标注实测时间点，可能被质疑不严谨。\", \"suggestion\": \"正片字幕明确‘10:02 到馆，排队 20 分钟’，口头说明‘当日场次’；活动规则以现场公示为准。\"}, {\"level\": \"high\", \"category\": \"广告未披露\", \"detail\": \"展会中品牌大量露出，口播若未持续强调无广，观众会误以为所有展位都是付费植入。\", \"suggestion\": \"开头、中段、结尾均重复‘自费无广’；如果后续接到合作，必须按 B 站规定注明‘广告’或‘赞助’。\"}, {\"level\": \"mid\", \"category\": \"引战\", \"detail\": \"把展会简单定义为‘拍照局’可能会惹反感，尤其对认真逛展或现场工作人员不友好。\", \"suggestion\": \"先呈现多类体验，再给出分类结论；不评价‘来拍照的人’，只说‘这个区域适合拍照’。\"}, {\"level\": \"low\", \"category\": \"数据时效误差\", \"detail\": \"票价和路线可能因官方调整而变化，视频发布后可能出现信息过时。\", \"suggestion\": \"在视频简介补充‘2026 年 4 月拍摄，信息以官方为准’，欢迎评论区更正，并置顶一条纠错评论。\"}]', '2026-08-24 05:37:40');
INSERT INTO `scripts` (`id`, `user_id`, `topic_id`, `idea_session_id`, `outline`, `shot_list`, `comments_text`, `script_json`, `cover_prompts_json`, `risks_json`, `created_at`) VALUES (2, 5, NULL, NULL, '主题：上海户外潮流展值不值得去\n1. 开头抛冲突：展会门票贵，到底是内容还是拍照局\n2. 到达国家会展中心，记录动线、排队、第一印象\n3. 三个展位深度体验：好看但买不到 / 能试穿 / 有品牌活动\n4. 商业化机会：联名、探店、线下活动怎么接\n5. 结论：适合哪类 UP、怎么拍才不踩坑', '相机+手机、稳定器、收音麦、展会票、充电宝、名片、备用口播提纲', '- 求完整路线和票价，别只拍好看的部分。\n- 开头 10 秒不知道在讲什么，建议直接抛冲突。\n- 想看真实排队和踩坑，不要只有精修镜头。\n- 适合周末两个人去吗？预算大概多少？\n- 封面信息太满，标题党了但内容还行。\n- 弹幕都在问合作品牌，希望说清楚是不是广告。\n- 后半段节奏掉了，体验过程可以再拆细一点。\n- 如果有「值不值得去」的结论会更好。', '{\"title\": \"宠物UP主探展：上海户外潮流展值不值？\", \"hook\": \"门票小一百，排队40分钟，上海户外潮流展到底值不值？别划走，这次我不剪精修，只讲真实体验。\", \"duration_hint\": \"建议成片4分30秒，3天内可完成拍摄剪辑\", \"shots\": [{\"time_range\": \"00:00-00:15\", \"camera\": \"手机前摄+稳定器，从展馆外快步走向镜头\", \"action\": \"UP主手持门票怼到镜头前，身后是排队人群，快步走入场。\", \"line\": \"门票小一百，排队40分钟，上海户外潮流展到底值不值？别划走，这次我不剪精修，只讲真实体验。\", \"interaction\": \"弹幕：值不值？\"}, {\"time_range\": \"00:15-00:40\", \"camera\": \"跟随+主观视角，叠加字幕框\", \"action\": \"拍地铁站出口指示牌、安检入口，字幕打出“完整动线见评论置顶”。\", \"line\": \"先回答评论问最多的：完整路线和票价。国家会展中心5.1馆，地铁2号线徐泾东站5号口最近；票价分工作日/周末，我买的是周日票，具体看官方公示。\", \"interaction\": \"评论区置顶：路线+票价表\"}, {\"time_range\": \"00:40-01:10\", \"camera\": \"固定机位，画面角落放计时器\", \"action\": \"镜头对着安检口排队人群，计时器从00:00跳到40:00，只加速不剪切。\", \"line\": \"说好的真实排队来了：周六上午10点安检口，我排了40分钟。没有VIP通道，带大包要开箱，建议少带东西。\", \"interaction\": \"弹幕：说排队就真拍排队\"}, {\"time_range\": \"01:10-01:40\", \"camera\": \"俯拍+特写，扫过联名周边和价格牌\", \"action\": \"走到一个户外品牌展位，拿起一款宠物联名胸背带，展示“只展示不卖”的立牌。\", \"line\": \"这个展位颜值最高，但联名款只展示不卖。工作人员说线上抽签，抽不抽得到全看命。\", \"interaction\": \"弹幕：抽签劝退\"}, {\"time_range\": \"01:40-02:10\", \"camera\": \"中景+特写，记录试穿全过程\", \"action\": \"和一位带小体型狗的观众商量后，在工作人员允许下给狗试穿雨衣30秒，狗一缩就脱，镜头切狗放松后的状态。\", \"line\": \"这个展位能试穿。注意，我只让狗穿了30秒，一缩就脱。科学试穿：看状态、别硬凹，更别为镜头吓动物。\", \"interaction\": \"弹幕：狗说达咩\"}, {\"time_range\": \"02:10-02:45\", \"camera\": \"广角+采访志愿者\", \"action\": \"走到公益领养信息墙前，镜头不怼笼子，只拍照片墙和志愿者，志愿者讲解流程。\", \"line\": \"这里不是卖货，是公益领养信息墙。流程是先填表、家访、签协议，不能现场带走。想领养先了解，别冲动。\", \"interaction\": \"弹幕：领养代替购买\"}, {\"time_range\": \"02:45-03:10\", \"camera\": \"个人口播，背景为休息区，画面出现“本期非广告”角标\", \"action\": \"UP主坐在休息区，对镜头说明合作边界；品牌物料出现时加“有合作”标签。\", \"line\": \"这期不是广告，票自己买的。刚才三个展位，只有一个在拍前说明优缺点、且允许我打标才接。接线下活动也一样：丑话说前面。\", \"interaction\": \"口播预埋：有异议评论区理性讨论\"}, {\"time_range\": \"03:10-03:40\", \"camera\": \"字幕版+小票特写\", \"action\": \"把地铁票、门票、餐饮小票铺在长椅上，字幕逐项累加。\", \"line\": \"这趟两个人，门票约260，地铁8，水30，午饭80-120，合计约400。不买东西，400封顶；要买联名周边，单件另算。\", \"interaction\": \"弹幕：预算可参考\"}, {\"time_range\": \"03:40-04:10\", \"camera\": \"展馆外逆光，边走边说\", \"action\": \"走回地铁站，用一句话总结值不值得。\", \"line\": \"结论：周末两个人适合来吗？喜欢拍照、逛新东西，可以来；想买到高性价比户外宠物装备，不建议。值不值，看你目的是什么。\", \"interaction\": \"评论区：你所在城市有这种展，你会去吗？\"}, {\"time_range\": \"04:10-04:30\", \"camera\": \"正面镜头，画面上方出现关注提示\", \"action\": \"UP主站定，手指向上方，示意点击关注。\", \"line\": \"完整动线、票价和踩坑清单我会放评论区置顶。这期就到这里，关注我，下期拆宠物户外装备怎么选。\", \"interaction\": \"三连+评论区提问，下期统一答\"}], \"cta\": \"关注+三连，评论区留下你的城市，下期做“宠物户外装备红黑榜”。\"}', '[{\"style\": \"高对比街拍\", \"prompt\": \"上海国家会展中心入口，UP主手持门票回头，身后排队人群，标题区留白，冷蓝调\"}, {\"style\": \"人物持证照\", \"prompt\": \"UP主站在展馆安检口，手机计时器显示40分钟，周围人流虚化，右下角放“真实排队”标签位\"}, {\"style\": \"宠物杂志摄影\", \"prompt\": \"小型犬穿雨衣蹲在展台边，主人低头观察，背景展品虚化，强调“30秒试穿”\"}, {\"style\": \"公益海报\", \"prompt\": \"领养信息墙前志愿者在讲解，逆光剪影，画面下方留白写“领养代替购买”\"}, {\"style\": \"测评账单风\", \"prompt\": \"地铁票、门票、小票摊在长椅上，咖啡杯压住，画面中间留标题区，干净背景\"}, {\"style\": \"双拼对比\", \"prompt\": \"左侧精修展台、右侧UP主瘫在休息区，中线分割，标题区写“别只拍好看”\"}]', '[{\"level\": \"high\", \"category\": \"未核实体验\", \"detail\": \"排队时长、门票价格、抽签规则、宠物入场政策均为个人现场观察，若口播成“官方数据”或被观众较真，容易翻车。\", \"suggestion\": \"所有数据标注“现场了解到/当天情况”；宠物能否入场需电话或官微确认后再剪进正片，不确定就说“以官方公告为准”。\"}, {\"level\": \"high\", \"category\": \"广告未披露\", \"detail\": \"合作展位或品牌若没收钱但存在赠票、样品置换，极易被弹幕质疑“恰饭”。\", \"suggestion\": \"所有合作/赠送票在开头或对应分镜口播标注；品牌素材加“广告”或“有合作”角标；保留“优缺点都放”的承诺。\"}, {\"level\": \"mid\", \"category\": \"夸大\", \"detail\": \"“只讲真实体验”“别划走”等表达若配合高高在上语气，容易被理解成标题党或拉踩，和评论反馈的“封面信息太满”冲突。\", \"suggestion\": \"标题和口播改为“个人体验”“这次的情况”，少用绝对化词；封面不要堆太多信息。\"}, {\"level\": \"mid\", \"category\": \"动物福利\", \"detail\": \"让狗试穿30秒虽已克制，但若狗状态紧张仍会被观众视为摆拍或伤害动物。\", \"suggestion\": \"正片加字幕“已征得主人同意，状态不好立即停止”；狗一旦明显抗拒就停止，并保留这一段作为科普素材。\"}]', '2026-08-24 11:46:23');
INSERT INTO `scripts` (`id`, `user_id`, `topic_id`, `idea_session_id`, `outline`, `shot_list`, `comments_text`, `script_json`, `cover_prompts_json`, `risks_json`, `created_at`) VALUES (3, 5, NULL, NULL, '主题：上海户外潮流展值不值得去\n1. 开头抛冲突：展会门票贵，到底是内容还是拍照局\n2. 到达国家会展中心，记录动线、排队、第一印象\n3. 三个展位深度体验：好看但买不到 / 能试穿 / 有品牌活动\n4. 商业化机会：联名、探店、线下活动怎么接\n5. 结论：适合哪类 UP、怎么拍才不踩坑', '相机+手机、稳定器、收音麦、展会票、充电宝、名片、备用口播提纲', '- 求完整路线和票价，别只拍好看的部分。\n- 开头 10 秒不知道在讲什么，建议直接抛冲突。\n- 想看真实排队和踩坑，不要只有精修镜头。\n- 适合周末两个人去吗？预算大概多少？\n- 封面信息太满，标题党了但内容还行。\n- 弹幕都在问合作品牌，希望说清楚是不是广告。\n- 后半段节奏掉了，体验过程可以再拆细一点。\n- 如果有「值不值得去」的结论会更好。', '{\"title\": \"上海户外潮流展：值回票价还是纯拍照局？\", \"hook\": \"门票一百多，到底能玩出什么花？有人说这是户外界的「网红打卡地」，也有人说逛完就俩字——就这？今天带上相机和任务清单，替你趟一遍，看完你再决定去不去。\", \"duration_hint\": \"8-10分钟\", \"shots\": [{\"time_range\": \"00:00-00:15\", \"camera\": \"手持自拍，正面近景，背景虚化人流\", \"action\": \"UP主站在展馆入口，举起门票怼镜头，转身指向排队的人群\", \"line\": \"一张票一百多，这里到底是内容展还是拍照局？走，今天咱亲眼去看看。\", \"interaction\": \"弹幕留言：等你避坑指南\"}, {\"time_range\": \"00:16-00:40\", \"camera\": \"GoPro挂在背包肩带，第一人称跟随走位\", \"action\": \"UP主走进排队通道，环顾四周，镜头扫过排队护栏和无尽的人头\", \"line\": \"周六早上十点，国家会展中心，给你们感受一下这个排队量。从入口到安检，预估15分钟打底，想来的朋友做好心理建设。\", \"interaction\": \"弹幕：这人也太多了吧\"}, {\"time_range\": \"00:41-01:20\", \"camera\": \"顺光中景，手机稳定器跟拍各展位外观，声音为现场收音加后期旁白\", \"action\": \"UP主穿过入口，用手机拍下展馆内整体布置，同时念出导览图上的分区信息\", \"line\": \"进来之后发现分四个大区，露营、装备、服饰、还有宠物区。记得先在门口拿导览图，不然你会在里面绕晕。\", \"interaction\": \"弹幕：宠物区？展开说说\"}, {\"time_range\": \"01:21-02:30\", \"camera\": \"从展位前方俯拍产品细节，再切至UP主手摸面料特写\", \"action\": \"UP主走向第一个展位——某户外椅子品牌，实物试坐，顺便翻看价格标签\", \"line\": \"这个展位是我最期待的，但你们看，商品全部仅供展示，不卖。想买？只能线上加购物车，现场连个折扣都不给。\", \"interaction\": \"弹幕：纯展示有啥好看的\"}, {\"time_range\": \"02:31-03:40\", \"camera\": \"跟随UP主脚步快速移动，镜头切到展位陈列，再切到UP主上身试穿冲锋衣\", \"action\": \"UP主找到能试穿的服饰展位，现场套上冲锋衣，对着镜子转圈展示，同时询问店员尺码和价格\", \"line\": \"这个展位终于能试穿了。我身上这件防风防水，面料是真舒服，就是价格嘛——嗯，大家自己看标签，我只能说懂的都懂。\", \"interaction\": \"\"}, {\"time_range\": \"03:41-04:50\", \"camera\": \"中景拍摄人群排队玩游戏，特写奖品；现场声音盖过旁白\", \"action\": \"UP主走到一个品牌活动区，看见大家排队玩投掷游戏赢小奖品，他站在一旁观察并采访一位刚玩完的路人\", \"line\": \"这边有个品牌活动，排队玩小游戏能拿徽章。我采访一下这位姐妹：排队排了多久？觉得值得吗？「排了半小时，赢了冰箱贴，就图一乐吧。」\", \"interaction\": \"弹幕：哈哈哈哈图一乐\"}, {\"time_range\": \"04:51-05:40\", \"camera\": \"手机低角度拍地面动线指示牌，穿插UP主在展馆间快步走的背影\", \"action\": \"UP主走到人少的角落，对着镜头展示手机步行记录和导览图，复盘刚才走的路线并指出一个容易错过的小展区\", \"line\": \"告诉你们一个省腿技巧：进门先奔右手边最里面，再往外逛。我刚刚就绕了一圈冤枉路，左边那个小展区差点错过。\", \"interaction\": \"弹幕：路书快抄一下\"}, {\"time_range\": \"05:41-06:30\", \"camera\": \"手持镜头，正面近景，背景为展馆出口方向\", \"action\": \"UP主站在休息区喝水，拿出笔记本，对着镜头念出自己记住的票价、停车费和餐饮价格\", \"line\": \"给大家算笔账：门票一百多，停车一小时八块，中午随便吃个工作餐五十。两个人来玩一天，不算买东西，开销大概小五百。\", \"interaction\": \"弹幕：双人成本马住\"}, {\"time_range\": \"06:31-07:20\", \"camera\": \"固定机位平视，UP主坐在展馆休息座椅上，语气放慢\", \"action\": \"镜头切回UP主总结：他对三个展位进行对比评价，给出「值不值得」的明确结论\", \"line\": \"总结一下：如果你是想认真看新产品、跟品牌聊聊天，值得来；但如果你只想拍照打卡，里面灯光其实一般，出片率不一定比得上免费公园。\", \"interaction\": \"评论区：去了的举个爪\"}, {\"time_range\": \"07:21-08:10\", \"camera\": \"延时摄影混剪，背景音乐渐起，画面为展台人流和日落时的展馆外景\", \"action\": \"镜头快速混剪当天拍摄的花絮：排队、试穿、路人采访、活动奖品，最后定格在展馆门口\", \"line\": \"对了，刚才我说那些合作品牌，没有任何一个是广告，纯自己买票逛的。如果主办方看到这期视频想找我合作——啊，那另说。\", \"interaction\": \"弹幕：广告打码就承认吧哈哈\"}, {\"time_range\": \"08:11-08:40\", \"camera\": \"手持自拍，站在展馆门口，夕阳背景\", \"action\": \"UP主边走边总结，对着镜头提出互动问题，画面叠加字幕「评论区聊聊你逛展的踩坑经历」\", \"line\": \"你逛过最坑的展是什么？或者有什么避雷经验？评论区聊聊，帮其他朋友排排雷。记得点赞关注，下次带你们去看更有意思的地方。\", \"interaction\": \"评论区：说说你被坑的经历\"}], \"cta\": \"点赞过万，下期就出「宠物区」单独逛展攻略，想看的朋友把「想看」打在公屏上。\"}', '[{\"style\": \"大字标题风\", \"prompt\": \"国展中心门口人山人海，UP主手持门票表情夸张，封面文字：排队1小时值不值？\"}, {\"style\": \"对比双拼风\", \"prompt\": \"左右分屏，左图精美帐篷装备，右图UP主摇头失望，封面文字：展会照骗？\"}, {\"style\": \"清单风\", \"prompt\": \"UP主站在展馆地图前指向路线，旁边文字列出：门票/停车/餐饮真实价格，标红『避坑』\"}, {\"style\": \"吐槽风\", \"prompt\": \"UP主抱臂站在空荡休息区，表情无奈，封面文字：这也能叫户外展？\"}, {\"style\": \"购物袋风\", \"prompt\": \"地面摊开展会的全部赠品徽章贴纸，UP主蹲在旁数数，封面文字：花了500块带回了这些\"}, {\"style\": \"Q版漫画风\", \"prompt\": \"Q版UP主被帐篷睡袋玩偶淹没，举着手机自拍，封面文字：户外人劝退现场\"}]', '[{\"level\": \"high\", \"category\": \"广告未披露\", \"detail\": \"视频中提及三个品牌展位，若后续收到品牌方合作或隐性赞助，未在画面和评论区置顶说明会被认定为软广。\", \"suggestion\": \"提前在视频简介和口播中声明「本期无任何商业合作」，所有品牌提及以客观体验为主，若产生合作需重新剪辑并标注广告标签。\"}, {\"level\": \"mid\", \"category\": \"夸大忽悠\", \"detail\": \"「值不值得」结论容易引发不同观点，且部分展位「价格贵」「不能试」的判断较主观，可能被指责评价不公。\", \"suggestion\": \"结论前增加对比维度：如与同类展会价格、免费公园出片率对比，强调「个人体感仅供参考」，避免绝对化措辞。\"}, {\"level\": \"mid\", \"category\": \"引战\", \"detail\": \"开头的「纯拍照局」和「就这」可能暗讽热衷打卡的观众，评论区容易变成「你去不起就别去」的互怼。\", \"suggestion\": \"在揭晓结论时补充「每个人的逛展目的不同，城市露营爱好者可能觉得值」，将吐槽集中在场馆设置而非观众选择。\"}, {\"level\": \"low\", \"category\": \"信息误导\", \"detail\": \"排队时长、票价等现场信息可能因日期或场次变化而失效，导致观众按旧信息行事。\", \"suggestion\": \"配音中交代「拍摄日期为2025年4月某周末」，并在简介区置顶评论更新官方票务渠道，务必标注「信息以现场为准」。\"}]', '2026-08-24 11:47:39');
INSERT INTO `scripts` (`id`, `user_id`, `topic_id`, `idea_session_id`, `outline`, `shot_list`, `comments_text`, `script_json`, `cover_prompts_json`, `risks_json`, `created_at`) VALUES (4, 5, 6, 7, '带狗排3小时，进店10分钟值得吗\n钩子：3小时排队换10分钟购物，我家狗子都不乐意了！\n角度：以宠物实际体验为核心，测评快闪店排队性价比与踩雷点，给出养宠人购物建议', '', '- 求完整路线和票价，别只拍好看的部分。\n- 开头 10 秒不知道在讲什么，建议直接抛冲突。\n- 想看真实排队和踩坑，不要只有精修镜头。\n- 适合周末两个人去吗？预算大概多少？\n- 封面信息太满，标题党了但内容还行。\n- 弹幕都在问合作品牌，希望说清楚是不是广告。\n- 后半段节奏掉了，体验过程可以再拆细一点。\n- 如果有「值不值得去」的结论会更好。', '{\"title\": \"带狗排3小时，进店10分钟值得吗\", \"hook\": \"带狗排3小时，进店10分钟，我家狗子直接不乐意了——这趟到底值不值？看完你就有数。\", \"duration_hint\": \"3-5分钟\", \"shots\": [{\"time_range\": \"0-15s\", \"camera\": \"近景，低机位怼脸拍狗\", \"action\": \"狗子坐在地上不肯走，主人拽牵引绳，狗子低头摆烂\", \"line\": \"带狗排3小时，进店10分钟，我家狗子直接不乐意了——这趟到底值不值？看完你就有数。\", \"interaction\": \"你们为毛孩子排过最久的队是多久？先弹幕打出来\"}, {\"time_range\": \"15-35s\", \"camera\": \"中景，手持跟拍排队队伍\", \"action\": \"镜头扫过排队长龙，停在快闪店门口，展示招牌和导流围栏\", \"line\": \"先说好：这条不是广告，全程自费，狗子亲自体验。今天测的是某广场宠物快闪店，周六下午两点，前面大概40人。门票免费，但进店要分时段。\", \"interaction\": \"弹幕刷“自费”让我看到\"}, {\"time_range\": \"35-55s\", \"camera\": \"侧面中景，拍狗和主人排队状态\", \"action\": \"狗子从站着变成趴下，主人蹲下给狗喝水，狗吐舌头喘气\", \"line\": \"排队一小时，狗子已经趴地上了。空气里全是别的狗狗的味道，它又兴奋又累。提醒一句：人多时及时给狗补水和休息。\", \"interaction\": \"\"}, {\"time_range\": \"55-75s\", \"camera\": \"过肩镜头，拍排队的前面小哥\", \"action\": \"小哥回头回答，手里拎着宠物袋，狗子在袋子里探头\", \"line\": \"前面小哥说，他们从浦东过来，就为了给猫买限定零食。我问他值吗，他苦笑了一下。对了，路线和票价我放在结尾。\", \"interaction\": \"如果是你，愿意为限定零食跨区跑一趟吗？\"}, {\"time_range\": \"75-95s\", \"camera\": \"广角跟拍进店，快速环视店内\", \"action\": \"店员发计时牌，狗子被抱起来，镜头扫过货架和网红拍照墙\", \"line\": \"终于进店，限时10分钟。店里确实好拍，但货架上的东西……我帮你看了，一半是贴牌网红款，成分表都不太透明。\", \"interaction\": \"\"}, {\"time_range\": \"95-115s\", \"camera\": \"中景，拍宠物泳池玩耍区\", \"action\": \"狗子在泳池边试水，脚碰水马上缩回来，主人抱走\", \"line\": \"这个泳池看着干净，但水温有点凉，小型犬下去容易着凉。店员说换水频率是每天一次，勉强及格。别被精修图骗了。\", \"interaction\": \"你家狗子怕水吗？评论区聊聊\"}, {\"time_range\": \"115-135s\", \"camera\": \"特写，拍商品价签和狗子闻零食\", \"action\": \"镜头对比店里价签和手机上的网上价格，狗子闻了闻袋子\", \"line\": \"踩雷点来了：同款零食，店里卖68，网上官方店39。建议只买现场限定，其他不要冲动。给狗子花钱，也得理性。\", \"interaction\": \"你们会现场买还是回家网购？\"}, {\"time_range\": \"135-155s\", \"camera\": \"中全景，拍拥挤的人群和一只小型犬\", \"action\": \"有只柯基从人群里钻过，主人赶紧抱起来，镜头拍到脚边差点被踩\", \"line\": \"第二个雷：人多的时候，小型犬特别危险，刚才有只柯基差点被踩。建议小型犬家长避开周末，真的，大型犬都挤。\", \"interaction\": \"带狗去人多的地方，你遇到过危险吗？\"}, {\"time_range\": \"155-175s\", \"camera\": \"固定机位，拍主人在路边石凳上算账\", \"action\": \"手机计算器画面叠加快镜头，狗子趴在脚边休息\", \"line\": \"两人一狗，地铁来回20，饮料40，最后买了包湿巾49。总花费109，排队3小时。这个数字给你们参考。\", \"interaction\": \"你觉得人均50以内的宠物店算贵吗？\"}, {\"time_range\": \"175-195s\", \"camera\": \"中景，主人面对镜头总结\", \"action\": \"狗子坐在旁边，主人摸摸狗头，镜头缓缓拉近\", \"line\": \"结论：如果你就在附近，工作日来逛逛可以；专程跨区来排队，真没必要。给狗子买日常用品，线上更香。这次体验仅代表当天情况。\", \"interaction\": \"你愿意带毛孩子排这种网红店吗？评论区理性讨论\"}, {\"time_range\": \"195-210s\", \"camera\": \"近景，狗子对镜头吐舌\", \"action\": \"狗子舔镜头，主人笑场，画面出现总结字幕和路线信息\", \"line\": \"想继续看宠物餐厅、宠物公园的实地测评，三连告诉我。评论区也会回复路线和票价问题，理性讨论，别上头。\", \"interaction\": \"下期想测宠物餐厅的扣1，宠物公园的扣2\"}], \"cta\": \"关注我，看更多带狗实测，不接没体验过的广告。\"}', '[{\"style\": \"写实摄影\", \"prompt\": \"狗趴地上无奈表情，背景排队人群虚化，大字“3小时换10分钟，值吗”，底部小字“真实测评”\"}, {\"style\": \"插画风\", \"prompt\": \"一只狗拖着主人从长队中走开，线条简洁，标题“网红宠物店踩雷？”，点缀购物袋和狗爪印\"}, {\"style\": \"电影感\", \"prompt\": \"主人在人群中抱狗，狗回头看向镜头，霓虹灯“快闪店”，画面偏蓝绿，氛围偏疲惫，留白放标题\"}, {\"style\": \"对比拼贴\", \"prompt\": \"左侧排队3小时人流长龙，右侧购物10分钟计时器，中间狗子表情对比，大字“踩雷？”\"}, {\"style\": \"可爱手绘\", \"prompt\": \"卡通狗举牌子“不建议专程来”，旁边列出“路费20元、饮料40元、湿巾49元”，背景简洁\"}, {\"style\": \"极简海报\", \"prompt\": \"狗头轮廓线稿，斜线分割，文字“排队3小时，进店10分钟”，大面积留白，高级冷淡风\"}]', '[{\"level\": \"mid\", \"category\": \"广告披露\", \"detail\": \"视频虽声明非广告，但快闪店品牌和商品有多次露出，可能被平台判定为隐性广告。\", \"suggestion\": \"在视频简介、置顶评论和画面角落明确标注“自费测评，无商业合作”，并保留购物小票证明自费。\"}, {\"level\": \"mid\", \"category\": \"夸大事实\", \"detail\": \"“3小时排队”和“10分钟购物”若缺少时间戳或完整记录，观众可能质疑标题党，引发负面讨论。\", \"suggestion\": \"在画面中加入排队开始/进店/离店的时间码字幕，并在台词里强调“本次体验数据”，避免绝对化表述。\"}, {\"level\": \"high\", \"category\": \"宠物福利\", \"detail\": \"让狗在拥挤人群中排队3小时，可能被观众批评忽视宠物福利，甚至引发“摆拍虐待”的舆论风险。\", \"suggestion\": \"增加狗子休息、喝水、被抱起的镜头，并口播提醒“随时观察宠物状态，累了就撤”。\"}, {\"level\": \"low\", \"category\": \"引战风险\", \"detail\": \"结论“线上更香”可能被解读为贬低实体店，引发评论区站队。\", \"suggestion\": \"改为“本次体验建议：日常囤货线上买，线下只花时间买限定”，强调个人经验，不拉踩。\"}]', '2026-08-24 11:52:28');
INSERT INTO `scripts` (`id`, `user_id`, `topic_id`, `idea_session_id`, `outline`, `shot_list`, `comments_text`, `script_json`, `cover_prompts_json`, `risks_json`, `created_at`) VALUES (5, 2, 14, 9, '专访里没说的数学真相\n钩子：你以为邓煜只是谦虚？官方通稿删掉了最狠的一句。\n角度：从专访原文逐句对比官方通稿，找出被删减的争议观点。', '', '- 求完整路线和票价，别只拍好看的部分。\n- 开头 10 秒不知道在讲什么，建议直接抛冲突。\n- 想看真实排队和踩坑，不要只有精修镜头。\n- 适合周末两个人去吗？预算大概多少？\n- 封面信息太满，标题党了但内容还行。\n- 弹幕都在问合作品牌，希望说清楚是不是广告。\n- 后半段节奏掉了，体验过程可以再拆细一点。\n- 如果有「值不值得去」的结论会更好。', '{\"title\": \"专访里没说的数学真相\", \"hook\": \"你以为邓煜只是谦虚？官方通稿删掉了最狠的一句——他原话直言同行工作‘只是技术活’，通稿改成了‘有压力’。\", \"duration_hint\": \"约10分钟体验vlog\", \"shots\": [{\"time_range\": \"0:00-0:15\", \"camera\": \"手持近景，快速切换\", \"action\": \"博主站在书店门口，左手拿一本旧杂志，右手拿一份通稿，对比着举到镜头前\", \"line\": \"你以为邓煜只是谦虚？官方通稿删掉了最狠的一句——他原话直言同行工作‘只是技术活’，通稿改成了‘有压力’。\", \"interaction\": \"弹幕应声：什么东西被删了？\"}, {\"time_range\": \"0:15-1:00\", \"camera\": \"中景跟拍，从街边走向书店\", \"action\": \"博主向镜头介绍今天的目的地，推开书店门\", \"line\": \"我是周末探店号。今天不探饭店，探一家大学路旧书店——据说藏着一篇被全面删减的数学家专访。\", \"interaction\": \"\"}, {\"time_range\": \"1:00-2:00\", \"camera\": \"固定机位拍门口排队，再切近景\", \"action\": \"博主排在队尾，擦汗，镜头扫过限流牌\", \"line\": \"没看错，周末来这家店也要排队。限流二十人，我们晒了十七分钟。真实排队，真实踩坑。\", \"interaction\": \"弹幕刷：真实\"}, {\"time_range\": \"2:00-3:00\", \"camera\": \"进入店内，手持跟随翻阅书架\", \"action\": \"博主在书架底部的过刊区翻找，最后抽出一本旧杂志\", \"line\": \"书架按年份排，过刊全在脚底下。这本《数学双周》2019年3月号，封面就是邓煜。蹲到脚麻才找到。\", \"interaction\": \"引导评论：需要完整路线图的评论区扣1\"}, {\"time_range\": \"3:00-4:30\", \"camera\": \"沙发区近景，翻页特写\", \"action\": \"博主翻开杂志内页，用红笔划出两行字，与官方通稿做对比\", \"line\": \"看这里：专访原话‘多数论文只是技术活，谈不上创新’。官方通稿变成‘青年学者面临很大压力’。这不是润色，是篡改。\", \"interaction\": \"弹幕：太敢说了\"}, {\"time_range\": \"4:30-6:00\", \"camera\": \"特写两页纸，镜头左右对比\", \"action\": \"博主拿笔指着另一段，念出删减部分\", \"line\": \"还有更狠的：专访里他说评审机制‘鼓励平庸’，通稿改成了‘建议完善评审流程’。一个在批判，一个在打圆场。\", \"interaction\": \"引导弹幕打‘品到了’\"}, {\"time_range\": \"6:00-6:30\", \"camera\": \"中景，博主放下杂志喝咖啡\", \"action\": \"博主突然想起什么，对着镜头郑重声明\", \"line\": \"声明一下：这期没有品牌合作，杂志五块淘的，咖啡自己买的。所以以下吐槽仅代表我个人。\", \"interaction\": \"弹幕：没恰饭，关注了\"}, {\"time_range\": \"6:30-7:30\", \"camera\": \"切换到吧台，拍菜单，再切到门口路牌\", \"action\": \"博主走到吧台拍价格牌，再走出门口拍路线指示\", \"line\": \"信息来了：地铁10号线A口出，左拐木棉巷走到底。低消一杯25元柠檬茶，没有强制续杯。周一闭店，别白跑。\", \"interaction\": \"\"}, {\"time_range\": \"7:30-8:15\", \"camera\": \"中景，博主坐在沙发区\", \"action\": \"博主拍了拍沙发坐垫，镜头转一圈扫过座位\", \"line\": \"两个人来也坐得下，但六个座位下午两点就被占满。想舒服看书就开门冲。预算两人八十到一百块，主要是饮料。\", \"interaction\": \"提问：你们觉得这个预算值得吗？\"}, {\"time_range\": \"8:15-8:45\", \"camera\": \"近景，博主低头插着充电器，皱眉\", \"action\": \"博主从墙角挪动位置，抱怨插座少\", \"line\": \"踩坑继续：全店只有两个插座，一个在吧台，一个在角落。我为了回血坐地上写了半小时稿，真实状况。\", \"interaction\": \"弹幕：插座太真实\"}, {\"time_range\": \"8:45-9:30\", \"camera\": \"手持走出书店，定格在门头\", \"action\": \"博主总结，给出值不值得去的结论\", \"line\": \"值不值得？如果冲着数学真相来，值，这店书够硬。如果想拍美照，别来，书堆成山，光线也不友好。\", \"interaction\": \"\"}, {\"time_range\": \"9:30-10:00\", \"camera\": \"近景，博主对着镜头比心\", \"action\": \"博主把杂志合起来，展示封面\", \"line\": \"可删减内容不止这些，完整文字版我放动态了。点赞过五千，下期就挖另一位科学家的专访删减。评论区你定。\", \"interaction\": \"三连+评论选人\"}], \"cta\": \"这期内容怕被删，建议先收藏。点赞过五千，下期挖另一位科学家的专访删减；投币数决定挖多深。评论区投票选人。\"}', '[{\"style\": \"复古报纸风\", \"prompt\": \"泛黄旧杂志特写，标题‘专访里没说的数学真相’，红笔划出被删句子，咖啡杯与眼镜，高对比，中文大字\"}, {\"style\": \"对比拼贴\", \"prompt\": \"左右分屏，左边官方通稿被打上马赛克，右边专访原话清晰，中间大问号，暗黑底，讽刺感，中文\"}, {\"style\": \"街头纪实\", \"prompt\": \"青年手拿两本翻开的杂志站在旧书店门口，一本写‘删’，一本写‘原话’，落叶，胶片颗粒，中文\"}, {\"style\": \"漫画夸张\", \"prompt\": \"Q版数学家从纸堆后探出，头顶气泡‘官方通稿删掉了最狠的一句’，鲜艳扁平插画，中文\"}, {\"style\": \"极简大字\", \"prompt\": \"纯色背景，一行大字‘他说了什么被删了？’，下方小字‘邓煜专访对比通稿’，无衬线，中文\"}, {\"style\": \"悬疑暗调\", \"prompt\": \"深夜旧书店，手电筒光照亮一本旧杂志，文字被红笔涂黑只剩一句，昏暗，紧张氛围，中文\"}]', '[{\"level\": \"high\", \"category\": \"未核实体验\", \"detail\": \"有关邓煜专访的引述内容为创作，未核实真实来源，可能被当事人及读者指出虚假，导致视频下架或投诉。\", \"suggestion\": \"在视频简介显著标注‘本文内容基于虚构设定，请勿当作真实访谈’；若可能，改用化名或模糊处理。\"}, {\"level\": \"mid\", \"category\": \"引战\", \"detail\": \"对同行‘技术活’和评审制度的批评可能激发数学圈粉丝对立，形成评论区骂战。\", \"suggestion\": \"表述时加上‘这是杂志原话，不代表本人观点’，避免直接认同或煽动。\"}, {\"level\": \"mid\", \"category\": \"广告未披露\", \"detail\": \"视频中出现的书店和咖啡店容易让人误以为有商业合作，若未声明则违反社区规范。\", \"suggestion\": \"在视频开头或声明处明确‘自费探店，无任何商业关系’，并在简介写明。\"}, {\"level\": \"low\", \"category\": \"夸大\", \"detail\": \"标题‘专访里没说的数学真相’和钩子‘最狠的一句’涉嫌标题党，若内容支撑不足可能被点踩。\", \"suggestion\": \"确保片头在15秒内真的抛出被删的关键句，且全片至少有两处具体对比内容。\"}]', '2026-08-24 13:14:07');
