INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (10, 1, '大闸蟹开捕季·阳澄湖防坑实录', '2026-09-20', '2026-10-31', '苏州阳澄湖', '去阳澄湖探访养殖户，辨别防伪标识，实测不同渠道的大闸蟹品质，给购买建议。', '大闸蟹礼券/养殖户', 'AI 自动捕捉', 'capture', '2026-08-24 05:46:31');
