INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (13, 1, '重阳节·带长辈吃的适老化餐厅体验', '2026-10-25', '2026-10-25', '广州', '探店针对老年人口味的清淡/软烂菜系，评估环境适老设施，讲清适不适合家庭聚餐。', '餐饮/养老相关品牌', 'AI 自动捕捉', 'capture', '2026-08-24 05:46:31');
