INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (16, 1, '阳光玫瑰葡萄跌到“白菜价”？批发市场价差实测', '2026-08-24', '2026-09-06', '广州江南果菜批发市场', '观众对网红水果价格崩盘有强共鸣，适合探店 UP 用线下比价+试吃给出「现在到底值不值得买」的结论，契合理性答疑人设。', '全程自费，无品牌赞助，避免影响结论。', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 05:54:29');
