INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (18, 1, '全家/罗森/711 秋季限定甜品测评：哪一款是热量骗子？', '2026-09-10', '2026-09-30', '上海、杭州、广州三城便利店连锁门店', '线下探店成本低，日更可持续，便利店受众年轻；适合做客观甜品横评并给出「配料表避雷」结论。', '无广，自购。', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 05:54:29');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (19, 1, '世界咖啡日：上海 5 家独立咖啡馆手冲盲测，贵一定好喝吗？', '2026-10-01', '2026-10-03', '上海永康路/武康路独立咖啡馆', '10 月 1 日国际咖啡日是天然流量节点，探店 UP 正好做「价格 vs 风味」的理性排雷，适合年轻人打卡。', '咖啡馆邀约需标注，建议至少一半自费。', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 05:54:29');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (20, 1, '今秋上海蟹黄面价格战：98 元和 388 元的差别到底在哪？', '2026-09-15', '2026-10-31', '上海蟹黄面专营店', '大闸蟹季下的细分切口，避开已做的阳澄湖防坑，用「同款餐品跨价格带对比」解决观众决策焦虑。', '餐厅可能合作，需注明拍摄是否免费。', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 05:54:29');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (21, 1, '五常新米上市：产地直发 vs 超市散装，盲吃对比', '2026-10-15', '2026-11-10', '哈尔滨五常/北京超市', '秋季新米是高频消费话题，UP 可实地探产地+超市盲测，给年轻人「怎么买不吃亏」的硬核结论。', '可能有米企赞助，需声明利益相关。', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 05:54:29');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (22, 1, '广州国际美食节扫雷：这 12 个摊头值得排队，4 个别碰', '2026-11-06', '2026-11-16', '广州', '日更探店 UP 适合做美食节「地图+排雷」，一次性覆盖多店，给出排队优先级，符合理性答疑。', '美食节组委会或摊主可能合作，必须露出「广告」标识。', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 05:54:29');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (23, 1, '2026 上海米其林指南发布：新晋一星店值得第一天就去排队吗？', '2026-11-16', '2026-11-22', '上海', '米其林发布是美食区年度热点，UP 可快速实地体验新被星餐厅，用「到底值不值」的结论帮观众省时间。', '餐厅可能邀请媒体，需明示是否免费/邀约；不虚夸。', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 05:54:29');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (24, 1, '2026 上海老字号鲜肉月饼排队实测：等 1 小时的和 5 分钟的差在哪？', '2026-09-01', '2026-09-09', '上海：光明邨、王家沙、泰康', '中秋前上海线下最典型的排队场景，画面有冲突感；体验派日更需要实拍多店对比，正好回答‘排队值不值’这种高频评论问题，也符合理性给依据的风格。', '无', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 05:57:29');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (25, 1, '2026 上海旅游节·老字号美食集市：10 元一份的限定小吃踩雷率有多高？', '2026-09-12', '2026-10-06', '上海 静安/豫园等旅游节市集', '一次性可以扫到多家老字号和网红摊位，适合做长视频场景；体验派可以用价格、排队时长、复购意愿三个指标给结论，评论区也能继续答疑‘哪家最值得专程去’。', '无', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 05:57:29');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (26, 1, '2026 丰收节·崇明直采 vs 菜市场：10 种时令菜价差到底有多大？', '2026-09-22', '2026-09-24', '上海崇明/市区菜市场', '把节气和价格战落到线下比价，是体验派擅长的一手实测题材；观众会追问产地直采到底是不是智商税，正好用数据回答。', '无', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 05:57:29');
