INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (30, 1, '2026 FHC 上海环球食品展观众日：专业展试吃真能吃到回本吗？', '2026-11-10', '2026-11-12', '上海新国际博览中心', '专业展自带大量高单价试吃（牛肉、芝士、橄榄油），适合做‘值回票钱’实测；体验派可以给出动线、签到、试吃排队策略，延续理性探店人设。', '无', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 05:57:29');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (31, 5, '开学季收拾书桌，翻出高三的倒计时本', '2026-09-01', '2026-09-03', '家', '开学季是生活区天然流量点，UP主用‘翻旧物’的方式切入，不用刻意煽情，旧物本身就能引发粉丝的集体回忆；结尾口播提问‘你想对高三的自己说什么’，正好用弹幕承接情绪。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:06:50');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (32, 5, '中秋前夜，我一个人做蛋黄酥翻车全过程', '2026-09-09', '2026-09-10', '家', '中秋容易拍成团圆煽情片，但TA更适合‘一个人也要好好过节’的陪伴视角，烘焙翻车既保留节日仪式感，又带来轻松笑点，和粉丝聊‘甜咸月饼’的弹幕不会冷场。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:06:50');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (33, 5, '上海旅游节首周，我花半价票在动物园看了两小时动物午睡', '2026-09-12', '2026-09-14', '上海野生动物园', '旅游节是生活区出行黄金档，但TA不拍赶场攻略，而用‘动物午睡’的慢节奏制造反差小钩子，符合‘日常切片’的叙事，粉丝会像和朋友一起散步那样跟着看完。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:06:50');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (34, 5, '国庆第一天，我去郊外稻田体验了一把人工割稻', '2026-10-01', '2026-10-02', '城市近郊农田', '国庆避开人流的近郊秋收，既有时间节点又接地气，正好延续TA的生活记录感；稻田、汗水、丰收这些场景自带情绪价值，结尾问‘你的假期最治愈瞬间’能有效带出弹幕。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:06:50');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (35, 5, '世界动物日，我在猫咖被一只橘猫霸占了背包', '2026-10-04', '2026-10-04', '猫咖', '动物日只是小切口，核心是记录‘人与猫的意外互动’，这与TA的轻松日常高度契合；被猫霸占背包的突发状况本身就是钩子，粉丝会纷纷来晒自己家宠物的怪癖。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:06:50');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (36, 5, '万圣节晚上，我准备了糖却被小区小孩一路跟到家', '2026-10-31', '2026-10-31', '小区', '万圣节是天然互动场，TA用‘被小孩讨糖’的社区小事替代猎奇装扮，氛围一出现就很有生活气息；结尾问‘你们小时候讨过糖吗’很容易引发怀旧弹幕。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:06:50');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (37, 5, '立冬下雨天，我把夏天的电风扇洗了个澡收起来', '2026-11-07', '2026-11-08', '家', '换季收纳是生活区常青话题，TA把它拍成‘和夏天说再见’的小仪式，情感温和不煽情，正好贴合陪伴感；粉丝会跟着讨论自己的换季习惯，互动率不会低。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:06:50');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (38, 5, '双十一前夜，我算了三小时满减最后只买了卷纸', '2026-11-10', '2026-11-11', '家', '双十一是全民消费话题，TA不晒战利品，用‘算不清账’的真实窘迫打消炫耀感，制造‘原来你也是普通人’的共鸣，弹幕会集体吐槽购物车，符合生活区氛围。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:06:50');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (39, 5, '十月傍晚，我循着桂花香在小区找到一棵树', '2026-10-15', '2026-10-16', '小区', '桂花香是秋天限定的感官体验，这种微小切入正好是TA的舒适区，不带目的‘找香味’的过程有散步陪伴感，视频里可以问‘你记忆里最好闻的秋天’，弹幕会聊得很软。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:06:50');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (40, 5, '开学第一天洗旧书包，从夹层里抖出一张三年前的拍立得', '2026-09-01', '2026-09-02', '自己的出租屋', '开学季节点落在旧物上，翻出拍立得能自然带出回忆，节奏是\'本来只是洗包突然有意外\'，很符合TA的日常转折拍摄方式，也方便弹幕聊自己的老物件。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:47:25');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (41, 5, '中秋给爸妈寄月饼，结果快递把它寄回了我自己家', '2026-09-08', '2026-09-10', '小区快递站', '用过中秋的仪式感来推倒剧情：寄礼物是常规操作，寄成乌龙是生活巧合；能讲独居青年与家人的牵挂，又不会太煽情，适合朋友聊天语气。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:47:25');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (42, 5, '国庆不去景点，我在菜市场跟一位阿姨学了挑板栗', '2026-10-01', '2026-10-03', '小区附近的菜市场', '黄金周反潮流留在城市，菜市场是烟火气最足的场景；跟阿姨学挑板栗的过程有交流、有步骤，能拍出\'被陌生人善意\'的小治愈，也和粉丝的买菜经历形成互动。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:47:25');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (43, 5, '万圣节我认真化了鬼脸妆，回到家猫被我吓到炸毛', '2026-10-31', '2026-11-01', '自己的家', '万圣节点只拿来当引子，不拍派对不拍路人，专注\'自己化妆+猫的真实反应\'，是生活区安全的可爱向素材，轻松又有小反转，适合做陪伴感的结尾梗。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:47:25');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (44, 5, '立冬前换被子，我把夏天的毛衣翻出来发现被虫蛀了个洞', '2026-11-05', '2026-11-07', '自己的家', '换季收纳是生活区超高频场景，蛀洞是每个人都遇到过的小遗憾；从\'收夏天\'到\'翻冬天\'的时间线很清晰，适合夹带一句节气感慨，也方便抛问题让弹幕说自己的衣柜惨剧。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:47:25');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (45, 5, '降温第一天，我用三个剩橙子煮了一壶热橙茶', '2026-11-12', '2026-11-15', '自己的厨房', '从天气变化自然进入做饭内容，剩橙子变热茶既省钱又有生活情调；不炫耀不教做菜，重点在\'冷天里给自己一点暖\'，贴合陪伴感定位。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:47:25');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (46, 5, '小区柿子树熟了，我够不到，只能等它自己掉下来', '2026-10-20', '2026-10-22', '小区楼下', '小区风物+等待的落差，是典型的小事小转折；拍仰望树、等落果的过程有真实时间感，很适合用\'结果\'连接情绪，观众也会分享他们小区里的水果树。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:47:25');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (47, 5, '去图书馆还一本迟到了一年的书，我做好了被收费的准备', '2026-09-15', '2026-09-16', '社区图书馆', '图书馆逾期是轻微社死现场，但把\'一年前借的书\'变成回忆入口，可以边还书边讲当时的生活；故事有完整起承转合，也符合不拍路人、不搞夸张的舒适区。', '', 'AI 按人设捕捉（未来90天）', 'capture', '2026-08-24 08:47:25');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (48, 5, '2026年秋季学期开学，我在家附近文具店被小学生的文具整不会了', '2026-09-01', '2026-09-01', '家附近文具店', '开学季是粉丝集体有感的节点，很适合拍日常小转折。具体角度：我先说结论，今天开学采购本来只想买个本子，结果在文具店看到现在小学生用的电动橡皮、自动削笔机，整个人有点懵。然后一路看一路试，最后买了一堆自己根本用不上的东西。结尾问粉丝：你们上学时有没有什么奇怪的文具执念？弹幕聊聊。', '', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-24 08:50:23');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (49, 5, '天猫99划算节，我在手机淘宝算满减算到半夜，结果只下了一单垃圾袋', '2026-09-09', '2026-09-09', '手机淘宝', '电商大促是生活区最日常的共鸣点，适合拍算满减翻车的陪伴感。具体角度：本来只想囤两卷垃圾袋，结果为了凑300-50把购物车加到三百多块，然后发现有一件不参加活动，又删掉重凑，最后半夜十二点下单时发现只便宜了五毛。结尾问：你们有没有为了满减越凑越多的经历？扣1让我看看。', '', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-24 08:50:23');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (50, 5, '2026世界清洁日，我在社区公园捡垃圾捡到一窝小猫', '2026-09-19', '2026-09-19', '社区公园', '世界清洁日自带公益和生活气，适合拍社区小意外。具体角度：和朋友去公园参加捡垃圾志愿活动，结果在灌木丛里听到小猫叫，垃圾袋瞬间变成小窝。然后我们一边捡垃圾一边喂猫，最后那窝小猫被路过的大姐领养了。结尾问：你们捡垃圾或者遛弯时有遇到过意外小惊喜吗？来评论区分享。', '', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-24 08:50:23');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (51, 5, '上海世博展览馆宠物用品展', '2026-09-04', '2026-09-04', '上海世博展览馆', '宠物展适合生活vlog，可拍逛展日常、试用宠物用品、偶遇猫狗互动，捕捉排队或翻车瞬间，结尾问观众二选一，制造陪伴感。', '', '下周五在上海世博展览馆有个宠物用品展，门票50元，很适合拍宠物友好探店', 'extract', '2026-08-24 10:37:38');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (52, 5, '2026国际狗狗日，我在上海给待领养狗狗拍领养证件照', '2026-08-26', '2026-08-26', '上海', '去领养日给待领养狗拍证件照和性格卡，开头用狗狗扑镜头制造治愈开场，推动领养。', '宠物洗护品牌可赞助待领养犬洗护及拍摄，展示领养潜力。', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-26 13:04:52');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (53, 5, '2026世界急救日，我去上海宠物医院学猫狗心肺复苏', '2026-09-12', '2026-09-12', '上海', '去宠物医院用模型演示猫狗心肺复苏与气道异物处理，不折腾活体，片尾提醒及时就医。', '宠物医院或宠物保险可提供拍摄场地并露出急救培训。', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-26 13:04:52');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (54, 5, '2026国际小熊猫日，我在上海动物园小熊猫馆拍丰容科普', '2026-09-19', '2026-09-19', '上海动物园小熊猫馆', '拍上海动物园小熊猫丰容，采访饲养员讲科学饲养与濒危保护，结尾引导关注正规动物园。', '动物园年卡或官方周边可在片尾做信息露出。', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-26 13:04:52');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (55, 5, '2026上海领养日，我在现场帮一只三脚猫找家，结果领养人问我它会不会拆家', '2026-09-12', '2026-09-12', '上海某商场中庭', '冲突：大家都嫌残疾猫，但猫很亲人；拍法：第一视角蹲守展位，拍猫狗互动与领养面试，科普领养协议/家访。', '宠物用品品牌可提供领养物资赞助', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-26 13:27:11');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (56, 5, '2026全国爱牙日，我扒开狗嘴闻了一下，发现它牙结石比我前任还多', '2026-09-20', '2026-09-20', '家里', '冲突：口臭/牙结石；拍法：镜头拍狗牙、尝试刷牙被躲，科普刷牙频率、洁牙零食测评。', '宠物洁牙零食/洁齿骨试用', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-26 13:27:11');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (57, 5, '2026世界阿尔茨海默病日，我家12岁老狗忘了自己的名字，但还记得我回家要开门', '2026-09-21', '2026-09-21', '家里', '情绪点：老狗认知障碍与依赖；拍法：固定镜头记录老狗转圈、撞门、呼唤无反应，字幕科普认知障碍。', '老年犬体检套餐测评', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-26 13:27:11');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (58, 5, '2026秋分，我把猫掉的毛搓成一颗球它追了三天，结果我发现那球里缠着它自己的屎', '2026-09-23', '2026-09-23', '家里', '反差：掉毛变玩具却翻车；拍法：收集猫毛、搓球、观察猫玩，中段科普换毛期梳毛和化毛。', '宠物梳毛器/粘毛器', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-26 13:27:11');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (59, 5, '2026中秋，我给猫做无糖宠物月饼，它闻了一下用爪子埋屎，我尝了一口懂了', '2026-09-25', '2026-09-25', '家里', '冲突：自制宠物月饼难吃；拍法：做月饼、猫埋屎动作、人试吃反应，科普中秋人食月饼不能喂宠物。', '宠物月饼/宠物烘焙DIY体验', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-26 13:27:11');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (60, 5, '2026世界无车日，我骑共享单车带猫出门，猫在包里叫得整条街以为我偷猫', '2026-09-22', '2026-09-22', '上海街头', '反差：想环保出行但猫恐慌；拍法：第一视角骑车、猫包内声音，科普带猫外出防应激。', '宠物背包/航空箱测评', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-26 13:27:11');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (61, 5, '2026抖音宠物‘被迫营业’挑战，我给狗穿上保安制服，结果它真的去门口看起了家', '2026-09-15', '2026-09-15', '家里/小区', '趣味反差：宠物穿职业装认真上班；拍法：跟拍狗穿制服后门卫行为，科普不强迫宠物穿难受衣服。', '宠物服饰品牌合作，需保证宠物舒适', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-26 13:27:11');
INSERT INTO `calendar_events` (`id`, `user_id`, `title`, `start_date`, `end_date`, `location`, `vlog_fit`, `commercial`, `raw_text`, `source`, `created_at`) VALUES (62, 5, '2026宠物秋日囤货节，我为了省30块凑单买了80斤猫砂，结果被楼管当成囤积癖', '2026-09-18', '2026-09-20', '家/快递点', '省钱爽点：满减凑单翻车；拍法：开箱大量猫砂、对比每公斤单价、科普囤货避坑临期。', '猫砂品牌大促优惠券', 'AI 按人设捕捉（未来30天）', 'capture', '2026-08-26 13:27:11');
